function liveReady(ctx){return !!(ctx&&ctx.state&&ctx.state.live&&window.GSM_LIVE&&window.GSM_LIVE.rpc&&window.BOOT&&BOOT.context);}
function liveIds(){const c=(window.BOOT&&BOOT.context)||{};return {ay:c.academic_year_id||null,term:c.term_id||null,ayName:c.academic_year||'—',termName:c.term||'—',ayStatus:c.academic_year_status||'—',termStatus:c.term_status||'—'};}
function msg(mount,title,body,kind){mount.innerHTML=window.GSM_pageHead(title,'Live Supabase operation')+`<div class="production-banner ${kind==='warn'?'warn':''}"><div>${kind==='warn'?'⚠':'✓'}</div><div>${body}</div></div>`;}
function autoCols(rows,max=10){if(!rows||!rows.length)return[];return Object.keys(rows[0]).filter(k=>!String(k).startsWith('__')).slice(0,max).map(k=>({key:k,label:titleCase(String(k).replace(/_/g,' '))}));}
function humanError(e){let x=String((e&&e.message)||e||'Unknown error');return x.replace(/^.*?message[:=]\s*/i,'').replace(/_/g,' ');}
function loading(mount,text){mount.innerHTML=`<div class="card"><div class="card-b"><div class="empty-state"><b>${esc(text||'Loading live data…')}</b></div></div></div>`;}


