V.reportconfig=function(mount,ctx){if(!liveReady(ctx)){msg(mount,'Report Configuration','Live sign-in required.','warn');return;}mount.innerHTML=window.GSM_pageHead('Report Configuration','Authoritative active report catalog from Supabase')+`<div class="production-banner"><div>✓</div><div><strong>LIVE CATALOG ONLY</strong><br>Workbook/local report definitions are not mixed into this production view.</div></div><div id="rcLive" style="margin-top:12px"><div class="empty-state">Loading live report catalog…</div></div>`;liveReportCatalog(ctx).then(rows=>window.GSM_DataTable({mount:byId('rcLive'),columns:[{key:'report_code',label:'Report ID'},{key:'report_name',label:'Report Name'},{key:'owner_role',label:'Owner Role'},{key:'service_group',label:'Module'},{key:'source_view',label:'Source'},{key:'primary_print',label:'Print'}],rows,pageSize:20,emptyMsg:'No active reports for this role.'})).catch(e=>byId('rcLive').innerHTML=`<div class="production-banner warn"><div>⚠</div><div>${esc(humanError(e))}</div></div>`);};
V.reportcenter=function(mount,ctx){
 if(!liveReady(ctx)){msg(mount,'Report Center','Live sign-in required.','warn');return;}const ids=liveIds();let reports=[],active=null,lastRows=[],lastCols=[];
 mount.innerHTML=window.GSM_pageHead('Report Center','Live Supabase reports · '+ids.ayName+' · '+ids.termName,`<button class="btn btn-outline btn-sm" id="rLiveRefresh">Refresh</button>`)+`<div class="production-banner"><div>✓</div><div><strong>LIVE REPORTS ONLY</strong><br>Every preview below is opened through the secured Supabase report RPC. No embedded workbook report data is used.</div></div><div class="table-toolbar" style="margin-top:12px"><label class="grow">Search Reports<input id="rLiveSearch" type="search" placeholder="Report name, code, role or module…"></label><label>Owner<select id="rOwner"><option value="">All visible roles</option></select></label></div><div id="rLiveGrid" class="report-card-grid"></div><div id="rLiveViewer" style="margin-top:14px"></div>`;
 function load(){byId('rLiveGrid').innerHTML='<div class="empty-state">Loading live report catalog…</div>';liveReportCatalog(ctx).then(r=>{reports=r||[];const roles=[...new Set(reports.map(x=>x.owner_role).filter(Boolean))].sort();byId('rOwner').innerHTML='<option value="">All visible roles</option>'+roles.map(x=>`<option>${esc(x)}</option>`).join('');draw();}).catch(e=>byId('rLiveGrid').innerHTML=`<div class="production-banner warn"><div>⚠</div><div>${esc(humanError(e))}</div></div>`)}
 function draw(){const q=byId('rLiveSearch').value.trim().toLowerCase(),owner=byId('rOwner').value;const list=reports.filter(r=>(!owner||r.owner_role===owner)&&(!q||[r.report_code,r.report_name,r.owner_role,r.service_group].join(' ').toLowerCase().includes(q)));byId('rLiveGrid').innerHTML=list.map(r=>`<article class="report-card" data-rpt="${esc(r.report_code)}"><div><div class="code">${esc(r.owner_role||'REPORT')} · ${esc(r.report_code)}</div><strong>${esc(r.report_name||r.report_code)}</strong></div><small>${esc(r.description||r.service_group||'Open live preview')}</small></article>`).join('')||'<div class="empty-state">No matching live reports.</div>';qsa('[data-rpt]',byId('rLiveGrid')).forEach(x=>x.onclick=()=>openReport(reports.find(r=>r.report_code===x.dataset.rpt)));}
 function openReport(r){if(!r)return;active=r;const v=byId('rLiveViewer');v.innerHTML=`<div class="card"><div class="card-h"><div><h3>${esc(r.report_code)} — ${esc(r.report_name||'Report')}</h3><div class="sub">${esc(r.description||'Live report preview')}</div></div><div class="page-actions"><button class="btn btn-outline btn-sm" id="rCloseLive">Close</button><button class="btn btn-primary btn-sm" id="rPrintLive">Print / PDF</button></div></div><div class="card-b"><div id="rPreviewLive"><div class="empty-state">Loading live report rows…</div></div></div></div>`;byId('rCloseLive').onclick=()=>v.innerHTML='';window.GSM_LIVE.rpc('get_report_preview',{p_report_code:r.report_code,p_limit:250}).then(d=>{lastRows=(d&&d.rows)||[];lastCols=autoCols(lastRows,12);window.GSM_DataTable({mount:byId('rPreviewLive'),columns:lastCols.length?lastCols:[{key:'NOTE',label:'Note'}],rows:lastRows,pageSize:25,emptyMsg:'No rows in this live report for the current context.'});}).catch(e=>byId('rPreviewLive').innerHTML=`<div class="production-banner warn"><div>⚠</div><div>${esc(humanError(e))}</div></div>`);byId('rPrintLive').onclick=()=>window.GSM_printReport({title:r.report_code+' — '+(r.report_name||'REPORT'),subTitle:'LIVE SUPABASE REPORT',ay:ids.ayName,term:ids.termName,columns:lastCols.length?lastCols:[{key:'NOTE',label:'Note'}],rows:lastRows,landscape:lastCols.length>7});}
 byId('rLiveRefresh').onclick=load;byId('rLiveSearch').oninput=draw;byId('rOwner').onchange=draw;load();
};

