// =====================================================================
// DOS — TIMETABLE GO-LIVE MANAGER
// =====================================================================
function embeddedTimetableBaseline(){
  try{
    const node=document.getElementById('rawWorkbookData');if(!node)return[];
    const all=JSON.parse(node.textContent||'{}'),sheet=all['65_TIMETABLE'];if(!sheet||!Array.isArray(sheet.v)||sheet.v.length<3)return[];
    const h=sheet.v[1];const ix=k=>h.indexOf(k);
    return sheet.v.slice(2).filter(r=>String(r[ix('STATUS')]||'').toUpperCase()==='PUBLISHED').map(r=>({class_code:r[ix('CLASS_ID')],subject_code:r[ix('SUBJECT_CODE')],day_of_week:r[ix('DAY_OF_WEEK')],period_code:r[ix('PERIOD_ID')],lesson_number:r[ix('LESSON_NUMBER')],start_time:r[ix('START_TIME')],end_time:r[ix('END_TIME')],lesson_type:r[ix('LESSON_TYPE')]||'NORMAL',room:r[ix('ROOM')]||null,status:'PUBLISHED'}));
  }catch(_){return[];}
}


