/* --- SERVICE RUNTIME block 6: gsm-r120-patch --- */

(function(){
'use strict';
if(!window.GSM_VIEWS||!window.GSM_MENUS||!window.GSM_LIVE||!window.GSM_UTIL)return;
const V=window.GSM_VIEWS,M=window.GSM_MENUS,U=window.GSM_UTIL;
const {esc,byId,qsa,toast}=U;
const rpc=(name,p={})=>window.GSM_LIVE.rpc(name,p);
const fmt=x=>x==null||x===''?'—':String(x);
const e=x=>esc(fmt(x));
const current=()=>{const c=(window.BOOT&&BOOT.context)||{};return {ay:c.academic_year||c.year_name||'—',term:c.term||c.term_code||'—'};};
const btnBusy=(id,text='Working…')=>{const b=byId(id);if(b){b.disabled=true;b.dataset.old=b.textContent;b.textContent=text;}};
const btnDone=id=>{const b=byId(id);if(b){b.disabled=false;b.textContent=b.dataset.old||b.textContent;}};
const errText=x=>(window.GSM_humanError?window.GSM_humanError(x):String((x&&x.message)||x||'Unknown error'));
const pill=s=>`<span class="pill ${String(s).toUpperCase()==='PUBLISHED'||String(s).toUpperCase()==='ACTIVE'?'green':String(s).toUpperCase()==='DRAFT'?'amber':'gray'}">${e(s)}</span>`;
const opt=(v,l,sel)=>`<option value="${esc(String(v??''))}"${String(v)===String(sel)?' selected':''}>${e(l)}</option>`;
const banner=(kind,title,msg)=>`<div class="production-banner ${kind||''}"><div>${kind==='warn'?'⚠':'✓'}</div><div><strong>${esc(title)}</strong><br>${esc(msg||'')}</div></div>`;

function embeddedTimetableBaselineR120(){
  try{
    const node=document.getElementById('rawWorkbookData');if(!node)return[];
    const all=JSON.parse(node.textContent||'{}'),sheet=all['65_TIMETABLE'];if(!sheet||!Array.isArray(sheet.v)||sheet.v.length<3)return[];
    const h=sheet.v[1],ix=k=>h.indexOf(k);
    return sheet.v.slice(2).filter(r=>String(r[ix('STATUS')]||'').toUpperCase()==='PUBLISHED').map(r=>({
      class_code:r[ix('CLASS_ID')],subject_code:r[ix('SUBJECT_CODE')],day_of_week:r[ix('DAY_OF_WEEK')],period_code:r[ix('PERIOD_ID')],
      lesson_number:r[ix('LESSON_NUMBER')],start_time:r[ix('START_TIME')],end_time:r[ix('END_TIME')],lesson_type:r[ix('LESSON_TYPE')]||'NORMAL',room:r[ix('ROOM')]||null,status:'PUBLISHED'
    }));
  }catch(_){return[];}
}

function renderValidation(v){
  if(!v)return '';
  const ok=!!v.valid;
  return `<div class="r120-validation ${ok?'ok':'bad'}"><b>${ok?'VALID — ready to publish':'ACTION REQUIRED'}</b><span>Rows ${e(v.rows)} · Class conflicts ${e(v.class_conflicts)} · Teacher conflicts ${e(v.teacher_conflicts)} · Missing period config ${e(v.missing_period_config)} · Assignment mismatch ${e(v.assignment_mismatch)}</span></div>`;
}



// Keep all existing menu links working but upgrade the timetable manager.


// Teacher timetable must come from the live published R120 feed, not local preview data.


// Make DOS navigation clearer: assignments + timetable configuration are one controlled workspace.
if(Array.isArray(M.DOS)){
  M.DOS.forEach(g=>{(g.items||[]).forEach(i=>{if(i.view==='r119_timetable_manager'){i.view='r120_timetable_manager';i.label='Timetable & Configuration';}if(i.view==='live_assignments'){i.view='r18612_teacher_assignments';i.label='Teacher Assignments';}});});
}
if(Array.isArray(M.SUPER_ADMIN))M.SUPER_ADMIN.forEach(g=>(g.items||[]).forEach(i=>{if(i.view==='r119_timetable_manager')i.view='r120_timetable_manager';}));

window.GSM_R120={release:'R120-TIMETABLE-CONFIGURATION',editable:true,assignmentSync:true,teacherFeed:true};
})();


;

