function head(t,s,a=''){return window.GSM_pageHead(t,s,a)}
function liveGuard(m,t){if(!window.BOOT||!window.GSM_LIVE.session()){m.innerHTML=head(t,'Live sign-in required.')+'<div class="production-banner warn"><div>!</div><div><strong>Sign in required.</strong><br>This screen does not use local fallback data.</div></div>';return false}return true}
function simpleTable(rows,cols,actions){if(!rows||!rows.length)return '<div class="empty-state">No records in the current context.</div>';return `<div class="r127-table-wrap"><table class="r127-table"><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}${actions?'<th>Action</th>':''}</tr></thead><tbody>${rows.map((r,i)=>`<tr>${cols.map(c=>`<td>${c.fmt?c.fmt(r[c.key],r):esc(val(r[c.key]))}</td>`).join('')}${actions?`<td>${actions(r,i)||''}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function printRows(title,rows,cols,landscape=true){const c=context();window.GSM_printReport({title,subTitle:'GS MUSUMBA SCHOOL MANAGEMENT SYSTEM — LIVE SUPABASE',ay:c.ay,term:c.term,columns:cols.map(x=>({key:x.key,label:x.label})),rows,landscape});}

const studentCache=new Map(),staffCache=new Map(),clubCache=new Map();
function studentLabel(id){const r=studentCache.get(String(id));return r?(r.sdms_code+' — '+r.full_name+(r.class_code?' · '+r.class_code:'')):String(id||'').slice(0,12)}
function staffLabel(id){const r=staffCache.get(String(id));return r?(r.staff_code+' — '+r.full_name):String(id||'').slice(0,12)}
function clubLabel(id){const r=clubCache.get(String(id));return r?(r.club_code+' — '+r.club_name):String(id||'').slice(0,12)}
async function loadStaff(){if(staffCache.size)return [...staffCache.values()];try{const d=await rpc('r126_get_staff_attendance',{p_attendance_date:today()});(d.rows||[]).forEach(r=>staffCache.set(String(r.staff_id),r));return d.rows||[]}catch(_){try{const d=await rpc('r127_get_secretary_context',{});(d.staff||[]).forEach(r=>staffCache.set(String(r.id),{...r,staff_id:r.id}));return d.staff||[]}catch(e){return[]}}}
async function loadClubs(){try{const d=await service('DOD_CLUBS');(d.rows||[]).forEach(r=>clubCache.set(String(r.id),r));return d.rows||[]}catch(_){return[]}}
async function searchStudents(q){const d=await rpc('r126_find_students',{p_query:q||null,p_limit:100});(d.rows||[]).forEach(r=>studentCache.set(String(r.student_id),r));return d.rows||[]}
async function uploadEvidence(file,category){if(!file)return null;const s=window.GSM_LIVE.session();if(!s||!s.access_token)throw new Error('LIVE_SESSION_REQUIRED');const safe=String(file.name||'evidence').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-90);const path=`${String(context().ay).replace(/[^a-zA-Z0-9_-]+/g,'_')}/${role()}/${String(category||'evidence').replace(/[^a-zA-Z0-9_-]+/g,'_')}/${Date.now()}_${safe}`;const url='https://xydrwpbgikwsxerqwkik.supabase.co/storage/v1/object/school-evidence/'+path;const res=await fetch(url,{method:'POST',headers:{apikey:'sb_publishable_-k49Hut2E8SNIJLvofL4JQ_jW1K865r',Authorization:'Bearer '+s.access_token,'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},body:file});if(!res.ok){let t=await res.text();throw new Error(t||('Evidence upload failed: HTTP '+res.status))}return 'storage://school-evidence/'+path}

