// STAFF ATTENDANCE — FULL WRITE WORKSPACE
// -------------------------------------------------------------------
V.r127_staff_attendance=function(mount){if(!liveGuard(mount,'Staff Attendance'))return;let rows=[];mount.innerHTML=head('Staff Attendance','Daily official staff attendance entry and monitoring',`<button class="btn btn-outline btn-sm" id="r127StaPrint">Print / PDF</button>`)+`<div class="r127-toolbar"><label>Attendance Date<input id="r127StaDate" type="date" value="${today()}"></label><button class="btn btn-outline" id="r127StaAll">Mark All Present</button><button class="btn btn-primary" id="r127StaSave">Save Attendance</button></div><div id="r127StaHost"><div class="empty-state">Loading staff…</div></div>`;
 const cols=[{key:'staff_code',label:'Staff Code'},{key:'full_name',label:'Full Name'},{key:'job_title',label:'Role'},{key:'attendance_status',label:'Status'},{key:'arrival_time',label:'Arrival'},{key:'departure_time',label:'Departure'},{key:'reason',label:'Reason'}];
 function draw(){byId('r127StaHost').innerHTML=`<div class="r127-table-wrap"><table class="r127-table"><thead><tr><th>#</th><th>Staff Code</th><th>Full Name</th><th>Role</th><th>Status</th><th>Arrival</th><th>Departure</th><th>Reason / Notes</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(val(r.staff_code))}</td><td><b>${esc(val(r.full_name))}</b></td><td>${esc(val(r.job_title))}</td><td><select data-sta="status" data-i="${i}">${['PRESENT','ABSENT','LATE','PERMISSION','LEAVE','OFF_DUTY'].map(x=>`<option ${String(r.attendance_status||'PRESENT').toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select></td><td><input data-sta="arrival" data-i="${i}" type="time" value="${esc(String(r.arrival_time||'').slice(0,5))}"></td><td><input data-sta="departure" data-i="${i}" type="time" value="${esc(String(r.departure_time||'').slice(0,5))}"></td><td><input data-sta="reason" data-i="${i}" value="${esc(r.reason||'')}"></td></tr>`).join('')}</tbody></table></div>`;qsa('[data-sta]',byId('r127StaHost')).forEach(el=>el.onchange=()=>{const r=rows[Number(el.dataset.i)],k=el.dataset.sta;if(k==='status')r.attendance_status=el.value;if(k==='arrival')r.arrival_time=el.value||null;if(k==='departure')r.departure_time=el.value||null;if(k==='reason')r.reason=el.value||null;});}
 function load(){byId('r127StaHost').innerHTML='<div class="empty-state">Loading staff attendance…</div>';rpc('r126_get_staff_attendance',{p_attendance_date:byId('r127StaDate').value}).then(d=>{rows=(d.rows||[]).map(r=>({...r,attendance_status:r.attendance_status||'PRESENT'}));rows.forEach(r=>staffCache.set(String(r.staff_id),r));draw();}).catch(e=>byId('r127StaHost').innerHTML=`<div class="production-banner warn"><div>!</div><div>${esc(human(e))}</div></div>`)}
 byId('r127StaDate').onchange=load;byId('r127StaAll').onclick=()=>{rows.forEach(r=>{r.attendance_status='PRESENT';if(!r.arrival_time)r.arrival_time=nowTime()});draw()};byId('r127StaSave').onclick=async()=>{const b=byId('r127StaSave');b.disabled=true;b.textContent='Saving…';try{const payload=rows.map(r=>({staff_id:r.staff_id,attendance_status:r.attendance_status||'PRESENT',arrival_time:r.arrival_time||null,departure_time:r.departure_time||null,reason:r.reason||null}));await rpc('r126_save_staff_attendance',{p_attendance_date:byId('r127StaDate').value,p_rows:payload});notice('Staff attendance saved successfully.');load()}catch(e){alert(human(e))}finally{b.disabled=false;b.textContent='Save Attendance'}};byId('r127StaPrint').onclick=()=>printRows('Staff Attendance Report',rows,cols,true);load();
};

