V.r127_staff_leave=function(mount){if(!liveGuard(mount,'Staff Leave / Official Movement'))return;let rows=[];mount.innerHTML=head('Staff Leave / Official Movement','Record staff movement; Headteacher/Super Admin approve or reject',`<button class="btn btn-outline btn-sm" id="r127LvPrint">Print / PDF</button>`)+`<div class="r127-grid"><div class="card"><div class="card-h"><h3>New Request / Movement</h3></div><div class="card-b"><div class="r127-form-grid"><label>Staff<select id="r127LvStaff"><option>Loading…</option></select></label><label>Level / Category<input id="r127LvLevel"></label><label>Destination<input id="r127LvDest"></label><label>Purpose<input id="r127LvPurpose"></label><label>Departure<input id="r127LvDep" type="datetime-local"></label><label>Expected Return<input id="r127LvRet" type="datetime-local"></label><label class="wide">Notes<textarea id="r127LvNotes"></textarea></label></div><div class="r127-actions"><button class="btn btn-primary" id="r127LvSave">Save Request</button></div></div></div><div class="card"><div class="card-h"><h3>Leave / Movement Register</h3><button class="btn btn-outline btn-sm" id="r127LvRefresh">Refresh</button></div><div class="card-b" id="r127LvHost"></div></div></div>`;loadStaff().then(rs=>byId('r127LvStaff').innerHTML='<option value="">— Select staff —</option>'+rs.map(r=>`<option value="${esc(String(r.staff_id||r.id))}">${esc((r.staff_code||'')+' — '+r.full_name)}</option>`).join(''));
 const cols=[{key:'departure_at',label:'Departure'},{key:'full_name',label:'Staff'},{key:'job_title',label:'Role'},{key:'destination',label:'Destination'},{key:'purpose',label:'Purpose'},{key:'return_at',label:'Return'},{key:'decision',label:'Decision',fmt:v=>statusPill(v)},{key:'approved_by_name',label:'Approved By'}];
 function draw(){const can=role()==='HEADTEACHER'||role()==='SUPER_ADMIN';byId('r127LvHost').innerHTML=simpleTable(rows,cols,can?r=>String(r.decision).toUpperCase()==='PENDING'?`<button class="btn btn-primary btn-sm" data-lv="APPROVED" data-id="${esc(r.id)}">Approve</button> <button class="btn btn-outline btn-sm" data-lv="REJECTED" data-id="${esc(r.id)}">Reject</button>`:'':null);if(can)qsa('[data-lv]',byId('r127LvHost')).forEach(b=>b.onclick=async()=>{b.disabled=true;try{await rpc('r127_decide_staff_leave',{p_id:b.dataset.id,p_decision:b.dataset.lv,p_notes:null});notice('Staff leave decision saved.');load()}catch(e){alert(human(e))}finally{b.disabled=false}})}
 async function load(){try{const d=await rpc('r127_get_staff_leave',{p_status:null});rows=d.rows||[];draw()}catch(e){byId('r127LvHost').innerHTML=`<div class="production-banner warn"><div>!</div><div>${esc(human(e))}</div></div>`}}
 byId('r127LvSave').onclick=async()=>{const b=byId('r127LvSave');b.disabled=true;try{await rpc('r127_save_staff_leave',{p_payload:{staff_id:byId('r127LvStaff').value,level_category:byId('r127LvLevel').value,destination:byId('r127LvDest').value,purpose:byId('r127LvPurpose').value,departure_at:byId('r127LvDep').value?new Date(byId('r127LvDep').value).toISOString():null,return_at:byId('r127LvRet').value?new Date(byId('r127LvRet').value).toISOString():null,notes:byId('r127LvNotes').value}});notice('Staff leave/movement request saved.');load()}catch(e){alert(human(e))}finally{b.disabled=false}};byId('r127LvRefresh').onclick=load;byId('r127LvPrint').onclick=()=>printRows('Staff Leave & Official Movement Report',rows,cols,true);load();
};

// -------------------------------------------------------------------
// SECRETARY MASTER DATA — STUDENT, STAFF, ENROLMENT
// -------------------------------------------------------------------
V.r127_secretary_center=function(mount){if(!liveGuard(mount,'Secretary / Master Data'))return;let classes=[],selectedStudent=null,selectedStaff=null;mount.innerHTML=head('Secretary / Master Data','No-code student, staff and class-enrolment administration')+`<div class="r127-tabs"><button class="r127-tab active" data-sec="students">Students</button><button class="r127-tab" data-sec="staff">Staff</button><button class="r127-tab" data-sec="enrol">Class Placement / Enrolment</button></div><div id="r127SecHost"></div>`;
 async function init(){try{const d=await rpc('r127_get_secretary_context',{});classes=d.classes||[];(d.staff||[]).forEach(r=>staffCache.set(String(r.id),{...r,staff_id:r.id}));show('students')}catch(e){byId('r127SecHost').innerHTML=`<div class="production-banner warn"><div>!</div><div>${esc(human(e))}</div></div>`}}
 function studentForm(d={}){return `<div class="r127-form-grid"><label>SDMS Code<input id="secSdms" value="${esc(d.sdms_code||'')}"></label><label>Full Name<input id="secName" value="${esc(d.full_name||'')}"></label><label>Sex<select id="secSex"><option value="MALE" ${String(d.sex||'').toUpperCase()==='MALE'?'selected':''}>Male</option><option value="FEMALE" ${String(d.sex||'').toUpperCase()==='FEMALE'?'selected':''}>Female</option></select></label><label>Date of Birth<input id="secDob" type="date" value="${esc(d.date_of_birth||'')}"></label><label>Father / Guardian Name<input id="secFgName" value="${esc(d.father_guardian_name||'')}"></label><label>Father / Guardian Phone<input id="secFgPhone" value="${esc(d.father_guardian_phone||'')}"></label><label>Mother / Guardian Name<input id="secMgName" value="${esc(d.mother_guardian_name||'')}"></label><label>Mother / Guardian Phone<input id="secMgPhone" value="${esc(d.mother_guardian_phone||'')}"></label><label>Sector<input id="secSector" value="${esc(d.sector||'')}"></label><label>Cell<input id="secCell" value="${esc(d.cell||'')}"></label><label>Village<input id="secVillage" value="${esc(d.village||'')}"></label><label>Status<select id="secStatus">${['ACTIVE','INACTIVE','TRANSFERRED','DROPPED_OUT','GRADUATED'].map(x=>`<option ${String(d.status||'ACTIVE').toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="r127-actions"><button class="btn btn-primary" id="secSaveStudent">${d.id?'Update Student':'Add Student'}</button><button class="btn btn-outline" id="secNewStudent">New / Clear</button></div>`}
 function show(which){qsa('[data-sec]',mount).forEach(b=>b.classList.toggle('active',b.dataset.sec===which));if(which==='students'){byId('r127SecHost').innerHTML=`<div class="r127-grid"><div class="card"><div class="card-h"><h3>Find / Edit Student</h3></div><div class="card-b"><div class="r127-toolbar"><input id="secStuQ" placeholder="Name, SDMS or class"><button class="btn btn-outline" id="secStuFind">Find</button></div><div id="secStuResults"></div></div></div><div class="card"><div class="card-h"><h3>Student Master Form</h3></div><div class="card-b" id="secStuForm">${studentForm()}</div></div></div>`;bindStudentForm();byId('secStuFind').onclick=async()=>{const rs=await searchStudents(byId('secStuQ').value);byId('secStuResults').innerHTML=simpleTable(rs,[{key:'sdms_code',label:'SDMS'},{key:'full_name',label:'Name'},{key:'sex',label:'Sex'},{key:'class_code',label:'Class'}],r=>`<button class="btn btn-outline btn-sm" data-editstu="${esc(String(r.student_id))}">Edit</button>`);qsa('[data-editstu]',byId('secStuResults')).forEach(b=>b.onclick=async()=>{try{selectedStudent=await rpc('r127_get_student_detail',{p_student_id:b.dataset.editstu});byId('secStuForm').innerHTML=studentForm(selectedStudent);bindStudentForm()}catch(e){alert(human(e))}})}}
 if(which==='staff'){byId('r127SecHost').innerHTML=`<div class="r127-grid"><div class="card"><div class="card-h"><h3>Active Staff Directory</h3></div><div class="card-b" id="secStaffList"></div></div><div class="card"><div class="card-h"><h3>Staff Master Form</h3></div><div class="card-b" id="secStaffForm"></div></div></div>`;loadStaff().then(rs=>{byId('secStaffList').innerHTML=simpleTable(rs,[{key:'staff_code',label:'Staff Code'},{key:'full_name',label:'Full Name'},{key:'phone',label:'Phone'},{key:'job_title',label:'Role'}],r=>`<button class="btn btn-outline btn-sm" data-editstaff="${esc(String(r.staff_id||r.id))}">Edit</button>`);qsa('[data-editstaff]',byId('secStaffList')).forEach(b=>b.onclick=async()=>{selectedStaff=await rpc('r127_get_staff_detail',{p_staff_id:b.dataset.editstaff});renderStaffForm(selectedStaff)})});renderStaffForm({})}
 if(which==='enrol'){byId('r127SecHost').innerHTML=`<div class="card"><div class="card-h"><h3>Class Placement / Enrolment</h3></div><div class="card-b"><div class="r127-form-grid"><label class="wide">Search Student<div class="r127-toolbar"><input id="secEnQ" placeholder="Name or SDMS"><button class="btn btn-outline" id="secEnFind">Find</button></div><select id="secEnStudent"><option value="">— Select student —</option></select></label><label>Class<select id="secEnClass"><option value="">— Select class —</option>${classes.map(c=>`<option value="${esc(c.id)}">${esc(c.class_code+' — '+c.class_name)}</option>`).join('')}</select></label><label>Status<select id="secEnStatus"><option>ACTIVE</option><option>PROMOTED</option><option>REPEATED</option><option>TRANSFERRED</option><option>DROPPED_OUT</option><option>COMPLETED</option><option>INACTIVE</option></select></label></div><div class="r127-actions"><button class="btn btn-primary" id="secEnSave">Save Class Placement</button></div></div></div>`;byId('secEnFind').onclick=async()=>{const rs=await searchStudents(byId('secEnQ').value);byId('secEnStudent').innerHTML='<option value="">— Select student —</option>'+rs.map(r=>`<option value="${esc(String(r.student_id))}">${esc(r.sdms_code+' — '+r.full_name+(r.class_code?' · current '+r.class_code:''))}</option>`).join('')};byId('secEnSave').onclick=async()=>{try{await rpc('r127_save_enrollment',{p_student_id:byId('secEnStudent').value,p_class_id:byId('secEnClass').value,p_status:byId('secEnStatus').value});notice('Student class placement saved.')}catch(e){alert(human(e))}}}
 }
 function bindStudentForm(){byId('secSaveStudent').onclick=async()=>{const p={id:selectedStudent&&selectedStudent.id||null,sdms_code:byId('secSdms').value,full_name:byId('secName').value,sex:byId('secSex').value,date_of_birth:byId('secDob').value||null,father_guardian_name:byId('secFgName').value,father_guardian_phone:byId('secFgPhone').value,mother_guardian_name:byId('secMgName').value,mother_guardian_phone:byId('secMgPhone').value,sector:byId('secSector').value,cell:byId('secCell').value,village:byId('secVillage').value,status:byId('secStatus').value};try{selectedStudent=await rpc('r127_save_student',{p_payload:p});notice('Student master saved.');byId('secStuForm').innerHTML=studentForm(selectedStudent);bindStudentForm()}catch(e){alert(human(e))}};byId('secNewStudent').onclick=()=>{selectedStudent=null;byId('secStuForm').innerHTML=studentForm({});bindStudentForm()}}
 function renderStaffForm(d){byId('secStaffForm').innerHTML=`<div class="r127-form-grid"><label>Staff Code<input id="secStCode" value="${esc(d.staff_code||'')}"></label><label>Full Name<input id="secStName" value="${esc(d.full_name||'')}"></label><label>Sex<select id="secStSex"><option value="">—</option><option value="MALE" ${String(d.sex||'').toUpperCase()==='MALE'?'selected':''}>MALE</option><option value="FEMALE" ${String(d.sex||'').toUpperCase()==='FEMALE'?'selected':''}>FEMALE</option></select></label><label>Phone<input id="secStPhone" value="${esc(d.phone||'')}"></label><label>Email<input id="secStEmail" type="email" value="${esc(d.email||'')}"></label><label>Job Title<input id="secStJob" value="${esc(d.job_title||'')}"></label><label class="r127-check"><input id="secStTeacher" type="checkbox" ${d.is_teacher?'checked':''}> Is Teacher</label><label>Status<select id="secStStatus">${['ACTIVE','INACTIVE','TRANSFERRED','LEFT'].map(x=>`<option ${String(d.status||'ACTIVE').toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="r127-actions"><button class="btn btn-primary" id="secStSave">${d.id?'Update Staff':'Add Staff'}</button><button class="btn btn-outline" id="secStNew">New / Clear</button></div>`;byId('secStSave').onclick=async()=>{const p={id:d.id||null,staff_code:byId('secStCode').value,full_name:byId('secStName').value,sex:byId('secStSex').value,phone:byId('secStPhone').value,email:byId('secStEmail').value,job_title:byId('secStJob').value,is_teacher:byId('secStTeacher').checked,status:byId('secStStatus').value};try{selectedStaff=await rpc('r127_save_staff',{p_payload:p});staffCache.set(String(selectedStaff.id),{...selectedStaff,staff_id:selectedStaff.id});notice('Staff master saved.');renderStaffForm(selectedStaff)}catch(e){alert(human(e))}};byId('secStNew').onclick=()=>{selectedStaff=null;renderStaffForm({})}}
 qsa('[data-sec]',mount).forEach(b=>b.onclick=()=>show(b.dataset.sec));init();
};

// -------------------------------------------------------------------
// BURSAR — FEES, PAYMENTS, RECEIPTS, INCOME/EXPENSE LEDGER
// -------------------------------------------------------------------
V.r127_finance_center=function(mount){
 if(!liveGuard(mount,'Finance Center'))return;
 let data={fee_items:[],payments:[]},student=null,ledger=[];
 mount.innerHTML=head('Bursar / Finance Center','Fee configuration, student payments, official receipts and income/expense ledger',`<button class="btn btn-outline btn-sm" id="finRefresh">Refresh</button>`)+`<div class="r127-tabs"><button class="r127-tab active" data-fin="payments">Student Payments</button><button class="r127-tab" data-fin="fees">Fee Configuration</button><button class="r127-tab" data-fin="ledger">Income / Expense Ledger</button></div><div id="finHost"></div>`;
 function active(){const b=qsa('[data-fin]',mount).find(x=>x.classList.contains('active'));return b?b.dataset.fin:'payments'}
 function canWrite(){return role()==='BURSAR'||role()==='SUPER_ADMIN'}
 async function load(){
  try{
   data=await rpc('r127_get_finance_center',{});
   try{const d=await service(role()==='HEADTEACHER'?'HT_FINANCE':'BUR_LEDGER');ledger=d.rows||[]}catch(_){ledger=[]}
   draw(active());
  }catch(e){byId('finHost').innerHTML=`<div class="production-banner warn"><div>!</div><div>${esc(human(e))}</div></div>`}
 }
 function paymentsView(){
  const can=canWrite();
  const total=(data.payments||[]).reduce((a,b)=>a+Number(b.paid_amount||0),0).toLocaleString();
  let form='';
  if(can){
   const feeOpts=(data.fee_items||[]).map(f=>`<option value="${esc(f.id)}">${esc(f.fee_name+' — '+Number(f.amount||0).toLocaleString()+' Frw')}</option>`).join('');
   form=`<div class="card"><div class="card-h"><h3>Record Student Payment</h3></div><div class="card-b"><div class="r127-toolbar"><input id="finStuQ" placeholder="Student name or SDMS"><button class="btn btn-outline" id="finStuFind">Find</button></div><select id="finStuSel"><option value="">— Select student —</option></select><div id="finPicked" class="r127-picked">No student selected.</div><div class="r127-form-grid"><label>Fee Item<select id="finFee">${feeOpts}</select></label><label>Paid Amount (Frw)<input id="finAmount" type="number" min="1"></label><label>Payment Date<input id="finDate" type="date" value="${today()}"></label><label>Method<select id="finMethod"><option>CASH</option><option>MOBILE_MONEY</option><option>BANK</option><option>OTHER</option></select></label><label>Transaction Ref<input id="finRef"></label><label>Notes<input id="finNotes"></label></div><div class="r127-actions"><button class="btn btn-primary" id="finPay">Save Payment + Receipt</button></div></div></div>`;
  }
  byId('finHost').innerHTML=`<div class="r127-kpis"><div class="r127-kpi"><b>${data.fee_count||0}</b><span>Fee Items</span></div><div class="r127-kpi"><b>${data.payment_count||0}</b><span>Payments Loaded</span></div><div class="r127-kpi"><b>${total}</b><span>Paid Amount (Frw)</span></div><div class="r127-kpi"><b>${esc(context().ay)}</b><span>Academic Year</span></div></div><div class="r127-grid">${form}<div class="card"><div class="card-h"><h3>Recent Payments</h3></div><div class="card-b" id="finPayList"></div></div></div>`;
  byId('finPayList').innerHTML=simpleTable(data.payments||[],[
   {key:'payment_date',label:'Date'},{key:'receipt_no',label:'Receipt'},{key:'student_name',label:'Student'},{key:'class_code',label:'Class'},{key:'fee_name',label:'Fee'},{key:'paid_amount',label:'Paid'},{key:'transaction_ref',label:'Reference'},{key:'status',label:'Status',fmt:v=>statusPill(v)}
  ],r=>`<button class="btn btn-outline btn-sm" data-receipt="${esc(r.id)}">Print Receipt</button>`);
  qsa('[data-receipt]',byId('finPayList')).forEach(b=>b.onclick=()=>printReceipt((data.payments||[]).find(r=>String(r.id)===b.dataset.receipt)));
  if(!can)return;
  byId('finStuFind').onclick=async()=>{const rs=await searchStudents(byId('finStuQ').value);byId('finStuSel').innerHTML='<option value="">— Select student —</option>'+rs.map(r=>`<option value="${esc(String(r.student_id))}">${esc(r.sdms_code+' — '+r.full_name+(r.class_code?' · '+r.class_code:''))}</option>`).join('')};
  byId('finStuSel').onchange=()=>{student=studentCache.get(byId('finStuSel').value)||null;byId('finPicked').innerHTML=student?`<b>${esc(student.full_name)}</b> · ${esc(student.sdms_code)} · ${esc(student.class_code||'—')}`:'No student selected.'};
  byId('finFee').onchange=()=>{const f=(data.fee_items||[]).find(x=>String(x.id)===byId('finFee').value);if(f)byId('finAmount').value=f.amount||''};
  if(byId('finFee').value)byId('finFee').onchange();
  byId('finPay').onclick=async()=>{if(!student){alert('Select a student first.');return}try{const rec=await rpc('r127_record_finance_payment',{p_payload:{student_id:student.student_id,fee_item_id:byId('finFee').value,paid_amount:byId('finAmount').value,payment_date:byId('finDate').value,payment_method:byId('finMethod').value,transaction_ref:byId('finRef').value,notes:byId('finNotes').value}});notice('Payment saved. Receipt: '+rec.receipt_no);await load();const fresh=(data.payments||[]).find(x=>x.receipt_no===rec.receipt_no);if(fresh)printReceipt(fresh)}catch(e){alert(human(e))}};
 }
 function feesView(){
  const can=canWrite();
  let form='';
  if(can)form=`<div class="card"><div class="card-h"><h3>Add / Update Fee Item</h3></div><div class="card-b"><div class="r127-form-grid"><label>Fee Code<input id="feeCode"></label><label>Fee Name<input id="feeName"></label><label>Amount (Frw)<input id="feeAmount" type="number" min="0"></label><label>Applies To<select id="feeApplies"><option>ALL_STUDENTS</option><option>CLASS</option><option>SEX</option><option>LEVEL</option></select></label><label>Applies Value<input id="feeValue"></label><label>Status<select id="feeStatus"><option>ACTIVE</option><option>INACTIVE</option><option>ARCHIVED</option></select></label><label class="r127-check"><input id="feeLocked" type="checkbox"> Locked</label></div><div class="r127-actions"><button class="btn btn-primary" id="feeSave">Save Fee Item</button></div></div></div>`;
  byId('finHost').innerHTML=form+`<div class="card" style="margin-top:12px"><div class="card-h"><h3>Configured Fee Items</h3></div><div class="card-b" id="feeList"></div></div>`;
  byId('feeList').innerHTML=simpleTable(data.fee_items||[],[{key:'fee_code',label:'Code'},{key:'fee_name',label:'Fee Name'},{key:'amount',label:'Amount'},{key:'applies_to',label:'Applies To'},{key:'applies_value',label:'Value'},{key:'payment_count',label:'Payments'},{key:'paid_total',label:'Paid Total'},{key:'status',label:'Status',fmt:v=>statusPill(v)}]);
  if(can)byId('feeSave').onclick=async()=>{try{await rpc('r127_save_finance_fee_item',{p_payload:{fee_code:byId('feeCode').value,fee_name:byId('feeName').value,amount:byId('feeAmount').value,applies_to:byId('feeApplies').value,applies_value:byId('feeValue').value,status:byId('feeStatus').value,locked:byId('feeLocked').checked}});notice('Fee item saved.');load()}catch(e){alert(human(e))}};
 }
 function ledgerView(){
  const can=canWrite();
  let form='';
  if(can)form=`<div class="card"><div class="card-h"><h3>Post Income / Expense</h3></div><div class="card-b"><div class="r127-form-grid"><label>Date<input id="ledDate" type="date" value="${today()}"></label><label>Type<select id="ledType"><option>INCOME</option><option>EXPENSE</option></select></label><label>Category<input id="ledCat"></label><label>Amount<input id="ledAmount" type="number" min="1"></label><label>Reference No.<input id="ledRef"></label><label>Description<input id="ledDesc"></label></div><div class="r127-actions"><button class="btn btn-primary" id="ledSave">Post Transaction</button></div></div></div>`;
  byId('finHost').innerHTML=form+`<div class="card" style="margin-top:12px"><div class="card-h"><h3>Finance Ledger</h3></div><div class="card-b" id="ledList"></div></div>`;
  byId('ledList').innerHTML=simpleTable(ledger,[{key:'transaction_date',label:'Date'},{key:'transaction_type',label:'Type',fmt:v=>statusPill(v)},{key:'category',label:'Category'},{key:'reference_no',label:'Reference'},{key:'description',label:'Description'},{key:'amount',label:'Amount'},{key:'status',label:'Status',fmt:v=>statusPill(v)}]);
  if(can)byId('ledSave').onclick=async()=>{try{await rpc('r127_save_finance_transaction',{p_payload:{transaction_date:byId('ledDate').value,transaction_type:byId('ledType').value,category:byId('ledCat').value,amount:byId('ledAmount').value,reference_no:byId('ledRef').value,description:byId('ledDesc').value}});notice('Finance transaction posted.');load()}catch(e){alert(human(e))}};
 }
 function draw(tab){qsa('[data-fin]',mount).forEach(b=>b.classList.toggle('active',b.dataset.fin===tab));if(tab==='fees')feesView();else if(tab==='ledger')ledgerView();else paymentsView()}
 function printReceipt(r){
  if(!r)return;const w=window.open('','_blank');if(!w){alert('Allow popups to print receipt.');return}
  w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(r.receipt_no)}</title><style>@page{size:A5 portrait;margin:12mm}body{font-family:Arial,sans-serif;color:#111}.box{border:1px solid #333;padding:18px}.c{text-align:center}table{width:100%;border-collapse:collapse;margin-top:14px}td{border:1px solid #333;padding:7px;font-size:12px}h1{font-size:17px}h2{font-size:14px}.sign{margin-top:35px;border-top:1px solid #333;width:220px;padding-top:5px;font-size:11px}</style></head><body><div class="box">${window.GSM_R18669_popupHeader('OFFICIAL PAYMENT RECEIPT','RECEIPT NO: '+(r.receipt_no||'—'))}<table><tr><td><b>Receipt No.</b></td><td>${esc(r.receipt_no)}</td></tr><tr><td><b>Date</b></td><td>${esc(val(r.payment_date))}</td></tr><tr><td><b>Student</b></td><td>${esc(val(r.student_name))}</td></tr><tr><td><b>SDMS</b></td><td>${esc(val(r.sdms_code))}</td></tr><tr><td><b>Class</b></td><td>${esc(val(r.class_code))}</td></tr><tr><td><b>Fee</b></td><td>${esc(val(r.fee_name))}</td></tr><tr><td><b>Paid Amount</b></td><td><b>${Number(r.paid_amount||0).toLocaleString()} Frw</b></td></tr><tr><td><b>Payment Method</b></td><td>${esc(val(r.payment_method))}</td></tr><tr><td><b>Transaction Ref.</b></td><td>${esc(val(r.transaction_ref))}</td></tr></table><p class="c">Generated from GS MUSUMBA SCHOOL MANAGEMENT SYSTEM.</p><div class="sign">Bursar / Authorized Signature</div></div><script>window.onload=()=>window.print()<\/script>
</body></html>`);
  w.document.close();
 }
 qsa('[data-fin]',mount).forEach(b=>b.onclick=()=>draw(b.dataset.fin));byId('finRefresh').onclick=load;load();
};

// -------------------------------------------------------------------
// HEADTEACHER APPROVALS
// -------------------------------------------------------------------
V.r127_approvals=function(mount){if(!liveGuard(mount,'Approvals & Evidence'))return;let leave=[],appeals=[],reports=[];mount.innerHTML=head('Approvals & Evidence','Leadership decisions that require authenticated approval')+`<div class="r127-tabs"><button class="r127-tab active" data-ap="leave">Staff Leave</button><button class="r127-tab" data-ap="appeals">Discipline Appeals</button><button class="r127-tab" data-ap="reports">Report Evidence</button></div><div id="apHost"></div>`;
 async function load(){try{const a=await Promise.all([rpc('r127_get_staff_leave',{p_status:'PENDING'}).catch(()=>({rows:[]})),window.GSM_LIVE.table('discipline_appeals','*').catch(()=>[]),service('HT_APPROVALS').catch(()=>({rows:[]}))]);leave=a[0].rows||[];appeals=(a[1]||[]).filter(x=>String(x.decision||'PENDING').toUpperCase()==='PENDING');reports=a[2].rows||[];draw(active())}catch(e){byId('apHost').innerHTML=`<div class="production-banner warn"><div>!</div><div>${esc(human(e))}</div></div>`}}
 function active(){return(qsa('[data-ap]',mount).find(b=>b.classList.contains('active'))||{}).dataset?.ap||'leave'}
 function draw(t){qsa('[data-ap]',mount).forEach(b=>b.classList.toggle('active',b.dataset.ap===t));if(t==='leave'){byId('apHost').innerHTML=simpleTable(leave,[{key:'departure_at',label:'Departure'},{key:'full_name',label:'Staff'},{key:'destination',label:'Destination'},{key:'purpose',label:'Purpose'},{key:'decision',label:'Decision',fmt:v=>statusPill(v)}],r=>`<button class="btn btn-primary btn-sm" data-aplv="APPROVED" data-id="${esc(r.id)}">Approve</button> <button class="btn btn-outline btn-sm" data-aplv="REJECTED" data-id="${esc(r.id)}">Reject</button>`);qsa('[data-aplv]',byId('apHost')).forEach(b=>b.onclick=async()=>{try{await rpc('r127_decide_staff_leave',{p_id:b.dataset.id,p_decision:b.dataset.aplv,p_notes:null});notice('Decision saved.');load()}catch(e){alert(human(e))}})}if(t==='appeals'){byId('apHost').innerHTML=simpleTable(appeals,[{key:'appeal_date',label:'Appeal Date'},{key:'student_id',label:'Student',fmt:v=>esc(studentLabel(v))},{key:'appeal_reason',label:'Reason'},{key:'review_notes',label:'Notes'},{key:'decision',label:'Decision',fmt:v=>statusPill(v)}],r=>`<button class="btn btn-primary btn-sm" data-apd="UPHELD" data-id="${esc(r.id)}">Uphold</button> <button class="btn btn-outline btn-sm" data-apd="REVISED" data-id="${esc(r.id)}">Revise</button> <button class="btn btn-outline btn-sm" data-apd="REJECTED" data-id="${esc(r.id)}">Reject</button>`);qsa('[data-apd]',byId('apHost')).forEach(b=>b.onclick=async()=>{try{await rpc('r127_decide_discipline_appeal',{p_id:b.dataset.id,p_decision:b.dataset.apd,p_notes:null});notice('Appeal decision saved.');load()}catch(e){alert(human(e))}})}if(t==='reports')byId('apHost').innerHTML=simpleTable(reports,[{key:'report_code',label:'Report Code'},{key:'report_name',label:'Report Name'},{key:'reporting_period',label:'Period'},{key:'submitted_date',label:'Submitted'},{key:'submitted_to',label:'Submitted To'},{key:'submission_status',label:'Status',fmt:v=>statusPill(v)},{key:'evidence_url',label:'Evidence'}]);}
 qsa('[data-ap]',mount).forEach(b=>b.onclick=()=>draw(b.dataset.ap));load();
};

