V.r127_system_health=function(mount){if(!liveGuard(mount,'System Health'))return;mount.innerHTML=head('System Health / Source Audit','Live production readiness from Supabase',`<button class="btn btn-outline btn-sm" id="healthRefresh">Refresh</button>`)+`<div id="healthHost"><div class="empty-state">Running live readiness checks…</div></div>`;async function load(){try{const d=await rpc('r123_production_readiness',{}),g=d.go_live||{},p=d.people||{},db=d.database||{},a=d.academic_period||{},rc=d.reconciliation||{},ds=d.data_state||{};const blockers=Object.entries(g).filter(([k,v])=>v===true&&/(required|pending)/.test(k));byId('healthHost').innerHTML=`<div class="r127-kpis"><div class="r127-kpi"><b>${db.tables||0}</b><span>Database Tables</span></div><div class="r127-kpi"><b>${db.rls_enabled||0}</b><span>RLS Protected Tables</span></div><div class="r127-kpi"><b>${p.active_student_master||0}</b><span>Student Master</span></div><div class="r127-kpi"><b>${p.active_staff||0}</b><span>Active Staff</span></div></div><div class="card"><div class="card-h"><h3>Production Readiness — ${esc(d.release||'R127')}</h3><span>${db.rls_complete?statusPill('RLS COMPLETE'):statusPill('RLS INCOMPLETE')}</span></div><div class="card-b"><div class="r127-health-row"><b>Current Enrolments</b><span>${esc(val(p.current_active_enrolments))}</span></div><div class="r127-health-row"><b>Classes</b><span>${esc(val(a.classes))}</span></div><div class="r127-health-row"><b>Teacher Assignments</b><span>${esc(val(a.assignments))}</span></div><div class="r127-health-row"><b>Timetable Entries</b><span>${esc(val(a.timetable_entries))}</span></div><div class="r127-health-row"><b>Academic Year / Term</b><span>${esc(val(a.academic_year))} (${esc(val(a.academic_year_status))}) · TERM 1 (${esc(val(a.term_1_status))})</span></div><div class="r127-health-row"><b>Missing Target Classes</b><span>${esc((rc.missing_target_classes||[]).join(', ')||'None')}</span></div><div class="r127-health-row"><b>Unexpected Classes</b><span>${esc((rc.unexpected_classes||[]).join(', ')||'None')}</span></div><div class="r127-health-row"><b>Timetable Data</b><span>${ds.timetable_ready?statusPill('READY'):statusPill('IMPORT REQUIRED')}</span></div><div class="r127-health-row"><b>Clubs Data</b><span>${ds.clubs_loaded?statusPill('READY'):statusPill('IMPORT REQUIRED')}</span></div><div class="r127-health-row"><b>Student Portal Accounts</b><span>${p.student_profiles||0}</span></div></div></div>${blockers.length?`<div class="production-banner warn" style="margin-top:12px"><div>!</div><div><strong>Go-live blockers still detected</strong><ul class="r127-warning-list">${blockers.map(([k])=>`<li>${esc(k.replace(/_/g,' '))}</li>`).join('')}</ul></div></div>`:`<div class="production-banner" style="margin-top:12px"><div>✓</div><div><strong>No readiness blockers detected.</strong></div></div>`}`;}catch(e){byId('healthHost').innerHTML=`<div class="production-banner warn"><div>!</div><div>${esc(human(e))}</div></div>`}}byId('healthRefresh').onclick=load;load();
};

