function renderBUR(mount,ctx,c,m){mount.innerHTML=`<div class="r128-role-shell">${hero('bur','BURSAR · FINANCE','FINANCE COMMAND CENTER','Fee configuration, student payments, receipts, balances and auditable finance operations.',m)}<div id="r128BurMoney" class="r128-money">${kpi('Collected','—','Current academic year','green')}${kpi('Payments','—','Posted transactions')}${kpi('Fee Items','5','Configured items','gold')}</div><div class="r128-grid-2">${panel('RECENT TRANSACTIONS','LIVE',`<div id="r128BurTx"><div class="r128-empty">Loading finance activity…</div></div>`)}${panel('FINANCE ACTIONS','BURSAR',`<div class="r128-actions">${action('Finance Center','Fees, payments, receipts and ledger.','r127_finance_center',{})}${action('Record Payment','Search student and issue receipt.','r127_finance_center',{tab:'payment'})}${action('Fee Configuration','Set fee items and amounts.','r127_finance_center',{tab:'fees'})}${action('Finance Reports','Print receipts, registers and summaries.','reportcenter',{})}</div>`)}</div>${panel('CONTROL RULES','FINANCE INTEGRITY',`<div class="r128-queue">${q('Receipts','Every posted student payment receives a unique receipt number.','AUTO','green')}${q('Auditability','Posted transactions remain traceable; reversal/void is controlled.','ON','green')}${q('Role Boundary','Bursar writes finance; Headteacher sees oversight; other roles are restricted.','RLS','green')}</div>`)}</div>`;bind(mount,ctx);rpc('r127_get_finance_center').then(d=>{const pays=d.payments||[],total=pays.reduce((s,x)=>s+num(x.paid_amount),0),fees=d.fee_items||[];const mh=mount.querySelector('#r128BurMoney');if(mh)mh.innerHTML=`${kpi('Collected',money(total),'Visible current-year payments','green')}${kpi('Payments',fmt(d.payment_count||pays.length),'Posted/visible transactions')}${kpi('Fee Items',fmt(d.fee_count||fees.length),'Active/configured fees','gold')}`;const th=mount.querySelector('#r128BurTx');if(th)th.innerHTML=pays.length?`<div style="overflow:auto"><table class="r128-table"><thead><tr><th>Date</th><th>Student</th><th>Fee</th><th>Amount</th><th>Receipt</th></tr></thead><tbody>${pays.slice(0,8).map(x=>`<tr><td>${esc(x.payment_date||'')}</td><td>${esc(x.student_name||x.sdms_code||'')}</td><td>${esc(x.fee_name||x.fee_code||'')}</td><td>${esc(money(x.paid_amount))}</td><td>${esc(x.receipt_no||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="r128-empty">No student payments recorded in the current academic year yet.</div>'}).catch(e=>{const h=mount.querySelector('#r128BurTx');if(h)h.innerHTML=`<div class="r128-empty">Finance summary unavailable: ${esc(e.message||e)}</div>`})}
