function workspace(mount,ctx,key){const cards=W[key]||[];const names={HEADTEACHER:'HEADTEACHER',DOS:'DOS · ACADEMIC SERVICES',DOD:'DOD · STUDENT AFFAIRS',SECRETARY:'SECRETARY · ADMINISTRATION',BURSAR:'BURSAR · FINANCE',SYSTEM:'SYSTEM MANAGEMENT'};mount.innerHTML='<div class="r132-page r132-workspace-'+String(key||'').toLowerCase()+'"><div class="r132-workspace-banner"><div><b>'+esc(names[key]||key)+' WORKSPACE</b><span>Canonical owner-based structure. Operational forms, monitoring and reports are not duplicated.</span></div><span class="r132-owner">SINGLE OWNER</span></div><div class="r132-card-grid">'+cards.map((c,i)=>'<article class="r132-card" data-r132-card="'+i+'"><div><h3>'+esc(c.title)+'</h3><p>'+esc(c.desc||'')+'</p></div><span>OPEN SERVICE</span></article>').join('')+'</div><div class="r132-report-strip"><div><b>REPORTS & PRINTED EVIDENCE</b><small>Reports open through the one Global Report Center; no duplicate report implementation.</small></div><button id="r132RoleReports">OPEN REPORTS</button></div><div id="r132Viewer"></div></div>';const host=q('#r132Viewer',mount);qa('[data-r132-card]',mount).forEach(el=>el.onclick=()=>{openSpec(host,ctx,cards[Number(el.dataset.r132Card)]);host.scrollIntoView({behavior:'smooth',block:'start'})});q('#r132RoleReports',mount).onclick=()=>openSpec(host,ctx,reportSpec((names[key]||key)+' Reports','Official reports and printed evidence.'))}

/* ---------- TEACHER 360 (Super Admin workspace, no duplicate edit forms) ---------- */


/* ---------- FULL STUDENT 360: all 1,101 records via REST pagination, not a 250-row slice ---------- */
let S360={all:[],filtered:[],page:1,pageSize:50,totalSource:0,mount:null,ctx:null,classes:new Map(),enrolments:[]};
function studentMap(r,enrol,classMap){const sid=String(r.id||r.student_id||''),sdms=String(r.sdms_code||r.student_code||r.code||'');const e=enrol.get(sid)||enrol.get(sdms)||{};const cid=String(e.class_id||e.class_code||r.class_id||r.class_code||'');const c=classMap.get(cid)||{};const cc=r.class_code||e.class_code||c.class_code||c.class_name||'';return{pk:sid||sdms,id:sdms||sid,name:r.full_name||r.student_name||r.name||'',sex:upper(r.sex||r.gender||''),class_code:cc,status:upper(r.status||r.student_status||(r.is_active===false?'INACTIVE':'ACTIVE')),year:e.academic_year||e.academic_year_name||r.academic_year||'',enrollment_status:upper(e.status||e.enrollment_status||''),parent:r.parent_contact||r.guardian_phone||r.father_guardian_phone||r.father_phone||r.mother_guardian_phone||r.mother_phone||'',raw:r,enrollment:e}}
function s360CurrentEnrollment(rows){const ay=(window.BOOT&&BOOT.context&&BOOT.context.academic_year_id)||'';const active=rows.filter(e=>(!ay||!e.academic_year_id||String(e.academic_year_id)===String(ay))&&!['INACTIVE','TRANSFERRED_OUT','DROPPED_OUT','CANCELLED'].includes(upper(e.status||e.enrollment_status)));const m=new Map();active.forEach(e=>{[e.student_id,e.student,e.sdms_code,e.student_code].filter(Boolean).map(String).forEach(id=>{if(id&&!m.has(id))m.set(id,e)})});return m}
function s360Level(cc){const m=String(cc||'').toUpperCase().match(/^(N\d*|P\d*|S\d*)/);return m?m[0].replace(/\d+$/,''):String(cc||'').charAt(0).toUpperCase()}
function s360Filter(){const m=S360.mount;if(!m)return;const lv=q('#s360Level',m).value,cl=q('#s360Class',m).value,sex=q('#s360Sex',m).value,st=q('#s360Status',m).value,term=upper(q('#s360Search',m).value);S360.filtered=S360.all.filter(x=>(!lv||s360Level(x.class_code)===lv)&&(!cl||x.class_code===cl)&&(!sex||x.sex===sex)&&(!st||x.status===st)&&(!term||[x.id,x.name,x.class_code,x.parent].join(' ').toUpperCase().includes(term)));S360.page=1;s360Render()}
function s360Render(){const m=S360.mount;if(!m)return;const rows=S360.filtered,pages=Math.max(1,Math.ceil(rows.length/S360.pageSize));S360.page=Math.max(1,Math.min(S360.page,pages));const start=(S360.page-1)*S360.pageSize,part=rows.slice(start,start+S360.pageSize),body=q('#s360Rows',m);const parentCell=(n,p)=>`<b>${esc(n||'—')}</b>${p?`<small class="r18669-parent-phone">${esc(p)}</small>`:''}`;body.innerHTML=part.length?part.map((x,i)=>'<tr><td>'+(start+i+1)+'</td><td><b>'+esc(x.id||'—')+'</b></td><td><b>'+esc(x.name||'—')+'</b></td><td>'+esc(x.sex||'—')+'</td><td>'+esc(x.class_code||'NO CURRENT CLASS')+'</td><td><span class="r132-pill '+(x.status==='ACTIVE'?'ok':x.status.includes('TRANSFER')?'warn':'bad')+'">'+esc(x.status||'—')+'</span></td><td>'+esc(x.enrollment_status||'—')+'</td><td class="r18669-parent">'+parentCell(x.father_name,x.father_phone)+'</td><td class="r18669-parent">'+parentCell(x.mother_name,x.mother_phone)+'</td><td><button class="r132-btn" data-profile="'+esc(x.pk||x.id)+'">PROFILE</button></td></tr>').join(''):'<tr><td colspan="10"><div class="r132-empty">No matching students.</div></td></tr>';q('#s360Showing',m).textContent='Showing '+(part.length?start+1:0)+'–'+Math.min(start+part.length,rows.length)+' of '+rows.length+' filtered · '+S360.all.length+' loaded';q('#s360PageInfo',m).textContent='PAGE '+S360.page+' / '+pages;q('#s360First',m).disabled=S360.page<=1;q('#s360Prev',m).disabled=S360.page<=1;q('#s360Next',m).disabled=S360.page>=pages;q('#s360Last',m).disabled=S360.page>=pages;q('#s360All',m).textContent=fmt(S360.all.length);q('#s360Classed',m).textContent=fmt(S360.all.filter(x=>x.class_code).length);q('#s360NoClass',m).textContent=fmt(S360.all.filter(x=>!x.class_code).length);q('#s360Active',m).textContent=fmt(S360.all.filter(x=>x.status==='ACTIVE').length);q('#s360Transferred',m).textContent=fmt(S360.all.filter(x=>x.status.includes('TRANSFER')).length);q('#s360Inactive',m).textContent=fmt(S360.all.filter(x=>x.status==='INACTIVE').length);q('#s360TotalSource',m).textContent=fmt(S360.totalSource||S360.all.length);qa('[data-profile]',m).forEach(b=>b.onclick=()=>s360Profile(S360.all.find(x=>String(x.pk||x.id)===String(b.dataset.profile))))}
async function s360ServiceRows(key){try{const d=await rpc('get_service_preview',{p_service_key:key,p_limit:2000});return d&&d.rows||[]}catch(_){return[]}}
function matchStudentRows(rows,x){const ids=[x.pk,x.id].map(String);const name=upper(x.name);return(rows||[]).filter(r=>{const rid=String(r.student_id||r.id||''),sd=String(r.sdms_code||r.student_code||''),nm=upper(r.student_name||r.full_name||'');return ids.includes(rid)||ids.includes(sd)||(name&&nm===name)})}
function miniTable(rows){if(!rows||!rows.length)return'<div class="r132-empty">No records available in this authorized source.</div>';const keys=Object.keys(rows[0]).filter(k=>!/(^id$|_id$|created_|updated_|school_id|auth_)/i.test(k)).slice(0,8);return'<div class="r132-table-wrap"><table class="r132-table" style="min-width:760px"><thead><tr>'+keys.map(k=>'<th>'+esc(k.replace(/_/g,' ').toUpperCase())+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,100).map(r=>'<tr>'+keys.map(k=>'<td>'+esc(safe(r[k]))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function s360Profile(x){if(!x)return;const m=S360.mount,box=q('#s360Profile',m);box.innerHTML='<div class="r132-profile"><div class="r132-profile-head"><div><h3>'+esc(x.name)+'</h3><small>SDMS '+esc(x.id)+' · '+esc(x.class_code||'NO CLASS')+' · '+esc(x.status)+'</small></div><span class="r132-owner">STUDENT 360</span></div><div class="r132-tabs">'+['PROFILE','ENROLMENT','ATTENDANCE','ACADEMICS','DISCIPLINE','WELFARE','ACTIVITIES','DOCUMENTS'].map((t,i)=>'<button class="r132-tab '+(!i?'active':'')+'" data-stab="'+t+'">'+t+'</button>').join('')+'</div><div class="r132-tab-body" id="s360TabBody"></div></div>';const body=q('#s360TabBody',box);
 const profile=()=>body.innerHTML='<div class="r132-no-dup">Profile and Enrolment are owned by Secretary; Attendance/Discipline/Welfare/Activities by DOD; Academics by DOS. This 360 page does not create duplicate edit forms.</div><div class="r132-info-grid" style="margin-top:8px">'+[['SDMS Code',x.id],['Full Name',x.name],['Sex',x.sex],['Class',x.class_code],['Student Status',x.status],['Enrolment Status',x.enrollment_status],['Father / Guardian',x.father_name],['Father Telephone',x.father_phone],['Mother / Guardian',x.mother_name],['Mother Telephone',x.mother_phone],['Source','Supabase + current enrolment']].map(a=>'<div class="r132-info"><b>'+esc(a[0])+'</b><span>'+esc(safe(a[1]))+'</span></div>').join('')+'</div><div class="r132-actions" style="margin-top:9px"><button class="r132-btn" id="s360EditOwner">EDIT STUDENT → SECRETARY</button></div>';
 async function tab(t){qa('[data-stab]',box).forEach(b=>b.classList.toggle('active',b.dataset.stab===t));body.innerHTML='<div class="r132-empty">Loading '+esc(t.toLowerCase())+'…</div>';if(t==='PROFILE'){profile();q('#s360EditOwner',body).onclick=()=>{const target=q('.side-link[data-id="r132_sa_sec"]');if(target)target.click()};return}if(t==='ENROLMENT'){body.innerHTML='<div class="r132-info-grid">'+Object.entries(x.enrollment||{}).filter(([k])=>!/(^id$|school_id|created_|updated_)/i.test(k)).slice(0,16).map(([k,v])=>'<div class="r132-info"><b>'+esc(k.replace(/_/g,' '))+'</b><span>'+esc(safe(v))+'</span></div>').join('')+'</div>';return}
 const map={ATTENDANCE:['DOD_CLASS_ATT'],ACADEMICS:['RESULTS'],DISCIPLINE:['DOD_DISCIPLINE'],WELFARE:['DOD_COUNSELLING','DOD_MEDICAL','DOD_SPECIAL_NEEDS','DOD_PARENT_WELFARE'],ACTIVITIES:['DOD_CLUB_ACTIVITIES','DOD_CLUBS'],DOCUMENTS:['DOD_DOCUMENTS']};const keys=map[t]||[];const sets=await Promise.all(keys.map(s360ServiceRows));let rows=[];sets.forEach((a,i)=>{const matched=matchStudentRows(a,x);matched.forEach(r=>rows.push(Object.assign({source_service:keys[i]},r)));});if(t==='ATTENDANCE'&&!rows.length&&sets[0]){rows=sets[0].filter(r=>String(r.class_code||'')===String(x.class_code)).map(r=>Object.assign({source_service:'DOD_CLASS_ATT',note:'Class-level monitoring context'},r));body.innerHTML='<div class="r132-status warn">Personal attendance-line detail is not exposed by the current preview service; showing authorized class-level attendance monitoring for '+esc(x.class_code||'this student')+'.</div>'+miniTable(rows);return}body.innerHTML=miniTable(rows)}
 qa('[data-stab]',box).forEach(b=>b.onclick=()=>tab(b.dataset.stab));profile();q('#s360EditOwner',body).onclick=()=>{const target=q('.side-link[data-id="r132_sa_sec"]');if(target)target.click()};box.scrollIntoView({behavior:'smooth',block:'start'})}
async function s360Load(){
 const m=S360.mount;
 q('#s360State',m).className='r132-status';
 q('#s360State',m).textContent='Loading complete 1,101-student master from secured R164 source…';
 try{
   const d=await rpc('r164_student_master_all',{});
   const students=(d&&d.rows)||[];
   S360.classes=new Map(); S360.enrolments=[];
   S360.all=students.map(r=>{
     const sid=String(r.id||r.student_id||''),sdms=String(r.sdms_code||r.student_code||''),cc=String(r.class_code||'');
     return{pk:sid||sdms,id:sdms||sid,name:r.full_name||r.student_name||'',sex:upper(r.sex||r.gender||''),class_code:cc,status:upper(r.status||'ACTIVE'),year:r.academic_year||'',enrollment_status:upper(r.enrollment_status||''),father_name:r.father_guardian_name||'',father_phone:r.father_guardian_phone||'',mother_name:r.mother_guardian_name||'',mother_phone:r.mother_guardian_phone||'',raw:r,enrollment:{id:r.enrollment_id||null,class_id:r.class_id||null,class_code:cc||null,class_name:r.class_name||null,level:r.level||null,academic_year:r.academic_year||'',enrollment_status:r.enrollment_status||''}};
   }).sort((a,b)=>String(a.name).localeCompare(String(b.name))||String(a.id).localeCompare(String(b.id)));
   S360.totalSource=Number(d&&d.row_count)||S360.all.length; S360.filtered=S360.all.slice();
   const cls=[...new Set(S360.all.map(x=>x.class_code).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true}));
   const levels=[...new Set(cls.map(s360Level).filter(Boolean))].sort(),statuses=[...new Set(S360.all.map(x=>x.status).filter(Boolean))].sort();
   q('#s360Class',m).innerHTML='<option value="">ALL CLASSES</option>'+cls.map(x=>'<option>'+esc(x)+'</option>').join('');
   q('#s360Level',m).innerHTML='<option value="">ALL LEVELS</option>'+levels.map(x=>'<option>'+esc(x)+'</option>').join('');
   q('#s360Status',m).innerHTML='<option value="">ALL STATUS</option>'+statuses.map(x=>'<option>'+esc(x)+'</option>').join('');
   if(S360.all.length===1101&&S360.totalSource===1101){q('#s360State',m).className='r132-status good';q('#s360State',m).textContent='COMPLETE LIVE STUDENT MASTER LOADED: 1,101 / 1,101. '+Number(d.with_current_enrolment||0)+' have a current class; '+Number(d.without_current_enrolment||0)+' remain visible as NO CURRENT CLASS.';}
   else{q('#s360State',m).className='r132-status warn';q('#s360State',m).textContent='Loaded '+fmt(S360.all.length)+' / '+fmt(S360.totalSource)+' active student-master records.';}
   s360Render();
 }catch(e){q('#s360State',m).className='r132-status warn';q('#s360State',m).textContent='Complete student master could not be loaded: '+String(e&&e.message||e);q('#s360Rows',m).innerHTML='<tr><td colspan="10"><div class="r132-empty">Live student data unavailable.</div></td></tr>';}
}
V.r132_student360=function(mount,ctx){S360={all:[],filtered:[],page:1,pageSize:50,totalSource:0,mount,ctx,classes:new Map(),enrolments:[]};mount.innerHTML='<div class="r132-page"><div class="r132-head"><div><h2>STUDENTS — STUDENT 360 WORKSPACE</h2><p>One search → one student profile → owner-specific records. No duplicate Secretary/DOS/DOD edit forms.</p></div><div class="r132-actions"><button class="r132-btn light" id="s360Refresh">REFRESH DATA</button><button class="r132-btn purple" id="s360Reports">STUDENT REPORTS</button></div></div><div class="r132-command"><label>LEVEL<select id="s360Level"><option value="">ALL LEVELS</option></select></label><label>CLASS<select id="s360Class"><option value="">ALL CLASSES</option></select></label><label>SEX<select id="s360Sex"><option value="">ALL SEX</option><option>MALE</option><option>FEMALE</option></select></label><label>STATUS<select id="s360Status"><option value="">ALL STATUS</option></select></label><label>SDMS / NAME / CLASS<input id="s360Search" placeholder="Search student..."></label><div class="r132-actions"><button class="r132-btn light" id="s360Clear">CLEAR</button></div></div><div id="s360State" class="r132-status">Preparing Student 360…</div><div class="r132-kpis"><div class="r132-kpi"><b id="s360TotalSource">—</b><span>Source Students</span></div><div class="r132-kpi good"><b id="s360All">—</b><span>Loaded Records</span></div><div class="r132-kpi good"><b id="s360Active">—</b><span>Active</span></div><div class="r132-kpi"><b id="s360Classed">—</b><span>With Class</span></div><div class="r132-kpi warn"><b id="s360NoClass">—</b><span>No Class</span></div><div class="r132-kpi warn"><b id="s360Transferred">—</b><span>Transferred</span></div><div class="r132-kpi bad"><b id="s360Inactive">—</b><span>Inactive</span></div></div><div class="r132-table-wrap"><table class="r132-table"><thead><tr><th>NO</th><th>SDMS</th><th>STUDENT</th><th>SEX</th><th>CLASS</th><th>STATUS</th><th>ENROLMENT STATUS</th><th>FATHER / GUARDIAN</th><th>MOTHER / GUARDIAN</th><th>PROFILE</th></tr></thead><tbody id="s360Rows"><tr><td colspan="10"><div class="r132-empty">Loading all students…</div></td></tr></tbody></table></div><div class="r132-pager"><div class="left"><span id="s360Showing">0 records</span><label>Rows <select id="s360PageSize"><option>25</option><option selected>50</option><option>100</option><option>200</option></select></label></div><div class="right"><button id="s360First">FIRST</button><button id="s360Prev">PREV</button><b id="s360PageInfo">PAGE 1 / 1</b><button id="s360Next">NEXT</button><button id="s360Last">LAST</button></div></div><div id="s360Profile"></div></div>';
 ['s360Level','s360Class','s360Sex','s360Status'].forEach(id=>q('#'+id,mount).onchange=s360Filter);q('#s360Search',mount).oninput=()=>{clearTimeout(S360._t);S360._t=setTimeout(s360Filter,120)};q('#s360Clear',mount).onclick=()=>{['s360Level','s360Class','s360Sex','s360Status','s360Search'].forEach(id=>q('#'+id,mount).value='');s360Filter()};q('#s360PageSize',mount).onchange=()=>{S360.pageSize=Number(q('#s360PageSize',mount).value)||50;S360.page=1;s360Render()};q('#s360First',mount).onclick=()=>{S360.page=1;s360Render()};q('#s360Prev',mount).onclick=()=>{S360.page--;s360Render()};q('#s360Next',mount).onclick=()=>{S360.page++;s360Render()};q('#s360Last',mount).onclick=()=>{S360.page=Math.ceil(S360.filtered.length/S360.pageSize)||1;s360Render()};q('#s360Refresh',mount).onclick=s360Load;q('#s360Reports',mount).onclick=()=>V.reportcenter(q('#s360Profile',mount),ctx);s360Load()};
V.students=V.r132_student360;

