function download(name,rows){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows],{type:'text/csv;charset=utf-8'}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},0)}
function randomPassword(len,mode){len=Math.max(1,Math.min(128,Number(len||8)));const sets={numeric:'0123456789',letters:'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz',mixed:'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789'};const chars=sets[mode]||sets.mixed,arr=new Uint32Array(len);crypto.getRandomValues(arr);return Array.from(arr,n=>chars[n%chars.length]).join('')}
