// ---------- USERNAME / PASSWORD CONTROL CENTER ----------
const CRED='GSM_R146_CREDENTIAL_REGISTER';
function credSaved(){try{return JSON.parse(localStorage.getItem(CRED)||'[]')}catch(_){return[]}}
function saveCred(x){if(!x||!x.temporary_password)return;const a=credSaved();a.unshift({full_name:x.full_name||'',staff_code:x.staff_code||'',phone:x.phone||'',username:x.username||'',login_email:x.login_email||'',password:x.temporary_password,created_at:new Date().toLocaleString()});localStorage.setItem(CRED,JSON.stringify(a.slice(0,500)))}
function csvCell(v){return '"'+String(v==null?'':v).replace(/"/g,'""')+'"'}
function download(name,rows){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows],{type:'text/csv;charset=utf-8'}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},0)}
function downloadCreds(list,label){const h=['FULL NAME','STAFF CODE','TELEPHONE','USERNAME','LOGIN EMAIL','TEMP PASSWORD'],lines=[h.map(csvCell).join(',')].concat((list||[]).map(x=>[x.full_name,x.staff_code,x.phone,x.username,x.login_email,x.temporary_password||x.password].map(csvCell).join(',')));download('GS_MUSUMBA_'+label+'_'+new Date().toISOString().slice(0,10)+'.csv',lines.join('\n'))}
function rand(len,mode){len=Math.max(1,Math.min(128,Number(len||8)));const sets={numeric:'0123456789',letters:'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz',mixed:'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789'},chars=sets[mode]||sets.mixed,a=new Uint32Array(len);crypto.getRandomValues(a);return Array.from(a,n=>chars[n%chars.length]).join('')}
async function edge(body){if(!L.refresh||!L.session)throw new Error('LIVE_SUPER_ADMIN_SESSION_REQUIRED');await L.refresh(false);let s=L.session();async function send(){const r=await fetch(SUPA+'/functions/v1/admin-temp-password',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+s.access_token,'Content-Type':'application/json'},body:JSON.stringify(body||{})});let d={};try{d=await r.json()}catch(_){}return{r,d}}let x=await send();if(x.r.status===401){await L.refresh(true);s=L.session();x=await send()}if(!x.r.ok||!x.d.success)throw new Error(x.d.detail||x.d.error||('HTTP '+x.r.status));return x.d}
async function edgeBulk(body){if(!L.refresh||!L.session)throw new Error('LIVE_SUPER_ADMIN_SESSION_REQUIRED');await L.refresh(false);let ss=L.session();async function send(){const r=await fetch(SUPA+'/functions/v1/admin-bulk-credentials-safe',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+ss.access_token,'Content-Type':'application/json'},body:JSON.stringify(body||{})});let d={};try{d=await r.json()}catch(_){}return{r,d}}let x=await send();if(x.r.status===401){await L.refresh(true);ss=L.session();x=await send()}if(!x.r.ok||!x.d.success)throw new Error(x.d.detail||x.d.error||x.d.msg||('HTTP '+x.r.status));return x.d}
V.r146_accounts=function(mount){let rows=[],filtered=[],catalog={roles:[],staff_without_profile:[]},selected=null;const roleOpts=(selectedRole='')=>(catalog.roles||[]).map(r=>`<option value="${esc(r.role_code)}" ${r.role_code===selectedRole?'selected':''}>${esc(r.role_name||r.role_code)}</option>`).join('');mount.innerHTML=`<div class="r146-page">${hero('USER ACCOUNTS & CREDENTIAL CONTROL CENTER','Fast user directory, telephone, username/password generator, custom password, missing-login sync and controlled bulk reset.','r146AC')}<div id="r146ACStatus" class="r146-statusbar">Loading live users…</div><div id="r146ACKpis"></div><section class="r146-account-editor"><h3>BULK USER GENERATOR & UPDATE</h3><p class="r146-note"><b>SYNC / UPDATE ALL USERS</b> creates only missing Auth logins and preserves every existing password. <b>RESET / GENERATE OTHER USER PASSWORDS</b> is a controlled bulk reset: it changes active user passwords but <b>NEVER resets the currently signed-in Super Admin</b>, so the administration session is not destroyed.</p><div class="r146-actions"><select id="r146BulkMode" class="r146-btn"><option value="numeric">NUMBERS ONLY</option><option value="letters">LETTERS ONLY</option><option value="mixed" selected>MIXED</option></select><input id="r146BulkLen" type="number" min="1" max="128" value="8" class="r146-btn" style="width:75px"><button id="r146SyncAll" class="r146-btn green">SYNC / UPDATE ALL USERS</button><button id="r146ResetAll" class="r146-btn red">RESET / GENERATE OTHER USER PASSWORDS</button><button id="r146CredDownload" class="r146-btn purple">DOWNLOAD SAVED CREDENTIALS</button></div><div id="r146BulkMsg" class="r146-statusbar warn" style="display:none"></div></section><section class="r146-account-editor" id="r146Editor"><h3>EDIT / UPDATE ONE USER</h3><div class="r146-account-form"><div class="r146-field"><label>Selected User</label><input id="r146Who" readonly placeholder="Choose MANAGE below"></div><div class="r146-field"><label>Username</label><input id="r146Username"></div><div class="r146-field"><label>Role</label><select id="r146Role"><option value="">SELECT ROLE</option></select></div><div class="r146-field"><label>Status</label><select id="r146Active"><option>ACTIVE</option><option>INACTIVE</option></select></div><div class="r146-field"><label>Custom / Generated Password</label><input id="r146Password" type="text" placeholder="Enter your own or generate"></div></div><div class="r146-actions" style="margin-top:8px"><select id="r146Mode" class="r146-btn"><option value="numeric">NUMBERS ONLY</option><option value="letters">LETTERS ONLY</option><option value="mixed" selected>MIXED</option></select><input id="r146Len" type="number" min="1" max="128" value="8" class="r146-btn" style="width:75px"><button id="r146GenPass" class="r146-btn orange">GENERATE PASSWORD</button><button id="r146GenUser" class="r146-btn" disabled>GENERATE USERNAME</button><button id="r146Save" class="r146-btn green" disabled>SAVE / UPDATE ACCOUNT</button></div><div id="r146EditMsg" class="r146-note"><b>Security note:</b> the generator accepts 1–128 characters, but Supabase Auth may reject a password shorter than the project security policy.</div></section><section class="r146-filters"><div class="r146-field search"><label>Search</label><input id="r146ACSearch" placeholder="Name, staff code, username, email or telephone"></div><div class="r146-field"><label>Role</label><select id="r146ACRole"></select></div><div class="r146-field"><label>Login Status</label><select id="r146ACLogin"><option value="">ALL LOGIN STATUS</option><option value="READY">LOGIN READY</option><option value="NOAUTH">NO AUTH LOGIN</option></select></div><div class="r146-field"><label>Rows / Page</label><select id="r146ACPer"><option>25</option><option selected>50</option><option>100</option><option>ALL</option></select></div></section><section class="r146-table-card"><div class="r146-table-title"><div><h3>LIVE USER DIRECTORY</h3><small>Telephone is read from STAFF, its single source of truth.</small></div><div class="r146-actions"><button id="r146AddToggle" class="r146-btn green">+ ADD NEW USER</button><button id="r146Directory" class="r146-btn purple">DOWNLOAD USER DIRECTORY</button></div></div><div class="r146-tablewrap"><table class="r146-table r18654-user-directory"><thead><tr><th>NO.</th><th>STAFF CODE / SDMS CODE</th><th>STAFF NAME</th><th>TELEPHONE</th><th>USERNAME</th><th>EMAIL</th><th>ROLE</th><th>EDIT / MANAGE</th></tr></thead><tbody id="r146ACBody"></tbody></table></div><div class="r146-pager"><div id="r146ACInfo" class="r146-pager-info"></div><div id="r146ACPages" class="r146-actions"></div></div></section><section class="r146-account-editor" id="r146Add" style="display:none"><h3>ADD NEW USER FROM ACTIVE STAFF</h3><div class="r146-account-form"><div class="r146-field"><label>Staff</label><select id="r146AddStaff"></select></div><div class="r146-field"><label>Role</label><select id="r146AddRole"></select></div><div class="r146-field"><label>Custom Username</label><input id="r146AddUser" placeholder="Blank = auto generate"></div><div class="r146-field"><label>Custom Password</label><input id="r146AddPass" placeholder="Blank = generate"></div><div class="r146-field"><label>Generator</label><select id="r146AddMode"><option value="numeric">NUMBERS ONLY</option><option value="letters">LETTERS ONLY</option><option value="mixed" selected>MIXED</option></select></div></div><div class="r146-actions" style="margin-top:8px"><input id="r146AddLen" type="number" min="1" max="128" value="8" class="r146-btn" style="width:75px"><button id="r146Create" class="r146-btn green">CREATE USER + SAVE</button></div><div id="r146AddMsg" class="r146-note">Only active staff without a user profile appear here.</div></section><section class="r146-table-card"><div class="r146-table-title"><div><h3>SAVED TEMP CREDENTIAL REGISTER — THIS BROWSER</h3><small>Download before clearing browser data. Plaintext temp passwords are intentionally local only.</small></div><button id="r146VaultClear" class="r146-btn red">CLEAR SAVED</button></div><div class="r146-tablewrap"><table class="r146-table" style="min-width:1000px"><thead><tr><th>NO.</th><th>USER</th><th>STAFF CODE</th><th>TELEPHONE</th><th>USERNAME</th><th>LOGIN EMAIL</th><th>TEMP PASSWORD</th><th>SAVED AT</th></tr></thead><tbody id="r146VaultBody"></tbody></table></div></section></div>`;
 let st={rows:[],page:1,pageSize:50,bodyId:'r146ACBody',infoId:'r146ACInfo',buttonsId:'r146ACPages',cols:[]};
 function renderVault(){const a=credSaved();q('#r146VaultBody',mount).innerHTML=a.length?a.map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.full_name)}</b></td><td>${esc(x.staff_code)}</td><td>${esc(x.phone||'—')}</td><td><b>${esc(x.username)}</b></td><td>${esc(x.login_email||'—')}</td><td><span class="r146-vault-secret">${esc(x.password)}</span></td><td>${esc(x.created_at)}</td></tr>`).join(''):'<tr><td colspan="8" class="r146-empty">No temporary credentials saved in this browser.</td></tr>'}
 function renderUsers(){const ps=q('#r146ACPer',mount).value==='ALL'?Math.max(1,filtered.length):Number(q('#r146ACPer',mount).value||50),pages=Math.max(1,Math.ceil(filtered.length/ps));st.page=Math.min(st.page,pages);const start=(st.page-1)*ps,part=filtered.slice(start,start+ps);q('#r146ACBody',mount).innerHTML=part.length?part.map((x,j)=>`<tr><td>${start+j+1}</td><td><b>${esc(x.staff_code||'—')}</b></td><td class="text-left"><b>${esc(x.full_name||'—')}</b></td><td><b>${esc(x.phone||'—')}</b></td><td><b>${esc(x.username||'—')}</b></td><td>${esc(x.email||x.login_email||'—')}</td><td><b>${esc(String(x.role_code||'—').replaceAll('_',' '))}</b></td><td><button class="r146-btn" data-ac-manage="${start+j}">MANAGE</button></td></tr>`).join(''):'<tr><td colspan="8" class="r146-empty">No matching users.</td></tr>';q('#r146ACInfo',mount).textContent=`Showing ${filtered.length?start+1:0}-${Math.min(start+ps,filtered.length)} of ${filtered.length} · Page ${st.page}/${pages}`;q('#r146ACPages',mount).innerHTML=`<button class="r146-btn" id="r146Prev" ${st.page<=1?'disabled':''}>‹ PREV</button><button class="r146-btn" id="r146Next" ${st.page>=pages?'disabled':''}>NEXT ›</button>`;q('#r146Prev',mount).onclick=()=>{st.page--;renderUsers()};q('#r146Next',mount).onclick=()=>{st.page++;renderUsers()};qa('[data-ac-manage]',mount).forEach(b=>b.onclick=()=>select(filtered[Number(b.dataset.acManage)]))}
 function filter(){const se=upper(q('#r146ACSearch',mount).value),ro=q('#r146ACRole',mount).value,li=q('#r146ACLogin',mount).value;filtered=rows.filter(x=>(!se||upper([x.full_name,x.staff_code,x.phone,x.username,x.email,x.role_code].join(' ')).includes(se))&&(!ro||x.role_code===ro)&&(!li||(li==='READY'?!!x.auth_user_id:!x.auth_user_id)));st.page=1;renderUsers()}
 function select(x){selected=x;q('#r146Who',mount).value=x?`${x.full_name} · ${x.staff_code} · ${x.phone||'NO PHONE'}`:'';q('#r146Username',mount).value=x?.username||'';q('#r146Role',mount).innerHTML='<option value="">SELECT ROLE</option>'+roleOpts(x?.role_code);q('#r146Active',mount).value=x?.status==='INACTIVE'?'INACTIVE':'ACTIVE';q('#r146Password',mount).value='';q('#r146Save',mount).disabled=!x;q('#r146GenUser',mount).disabled=!x;q('#r146Editor',mount).scrollIntoView({behavior:'smooth',block:'start'})}
 async function load(){const sb=q('#r146ACStatus',mount);sb.className='r146-statusbar';sb.innerHTML='<b>Loading live account directory…</b>';try{if(L.refresh)await L.refresh(false).catch(()=>{});const [d,staff]=await Promise.all([L.rpc('r135_admin_user_accounts',{}),L.table('staff','*').catch(()=>[])]);let edgeWarn='';try{catalog=await edge({action:'catalog'})||catalog}catch(ex){edgeWarn=String(ex&&ex.message||ex);catalog=catalog||{roles:[],staff_without_profile:[]}}const mapId=new Map((staff||[]).map(x=>[String(x.id),x])),mapCode=new Map((staff||[]).map(x=>[String(x.staff_code||''),x]));rows=(d?.rows||[]).map(x=>{const s=mapId.get(String(x.staff_id||''))||mapCode.get(String(x.staff_code||''))||{};return{...x,phone:x.phone||s.phone||'',email:x.email||s.email||''}});filtered=rows.slice();const roleSource=(catalog.roles&&catalog.roles.length)?catalog.roles:[...new Map(rows.filter(x=>x.role_code).map(x=>[x.role_code,{role_code:x.role_code,role_name:x.role_name||x.role_code}])).values()];catalog.roles=roleSource;q('#r146ACRole',mount).innerHTML='<option value="">ALL ROLES</option>'+roleOpts('');q('#r146AddRole',mount).innerHTML=roleOpts('TEACHER');q('#r146AddStaff',mount).innerHTML='<option value="">SELECT STAFF WITHOUT PROFILE</option>'+(catalog.staff_without_profile||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.full_name)} · ${esc(x.staff_code)} · ${esc(x.phone||'NO PHONE')}</option>`).join('');q('#r146ACKpis',mount).innerHTML=kpis([{v:rows.length,l:'USER PROFILES'},{v:rows.filter(x=>x.auth_user_id).length,l:'LOGIN READY',c:'good'},{v:rows.filter(x=>!x.auth_user_id).length,l:'NO AUTH LOGIN',c:'bad'},{v:rows.filter(x=>x.role_code==='TEACHER').length,l:'TEACHERS'},{v:(catalog.staff_without_profile||[]).length,l:'STAFF WITHOUT PROFILE',c:'warn'},{v:rows.filter(x=>x.phone).length,l:'USERS WITH TELEPHONE',c:'purple'}]);sb.className=edgeWarn?'r146-statusbar warn':'r146-statusbar good';sb.innerHTML=edgeWarn?'<b>USER DIRECTORY LOADED.</b> Staff and accounts are visible. Credential controls are temporarily unavailable: '+esc(edgeWarn):'<b>LIVE ACCOUNT DIRECTORY + CREDENTIAL CONTROL LOADED.</b> Staff list, username/password update and bulk credential actions are available.';filter();renderVault()}catch(e){const em=String(e&&e.message||e||'');sb.className='r146-statusbar bad';if(/refresh token|session|jwt|token.*not found|invalid.*token/i.test(em)){sb.innerHTML='<b>ADMIN SESSION NEEDS RE-LOGIN.</b> '+esc(em)+' <b>This is not a staff-directory data loss.</b> Sign in again, then press REFRESH.'}else{sb.innerHTML='<b>ACCOUNT DIRECTORY LOAD FAILED:</b> '+esc(em)+' <b>Try REFRESH after re-login if the session expired.</b>'}}}
 async function save(){if(!selected)return;const msg=q('#r146EditMsg',mount);try{const d=await edge({action:'save_account',profile_id:selected.profile_id,username:q('#r146Username',mount).value.trim(),role_code:q('#r146Role',mount).value,is_active:q('#r146Active',mount).value==='ACTIVE',password:q('#r146Password',mount).value||undefined});saveCred({...d,phone:selected.phone});msg.innerHTML=`<b>SAVED:</b> ${esc(d.full_name||selected.full_name)} · ${esc(d.username)}${d.temporary_password?` · Temp password <span class="r146-vault-secret">${esc(d.temporary_password)}</span>`:''}`;await load()}catch(e){msg.innerHTML='<b>UPDATE FAILED:</b> '+esc(e.message||e)}}
 async function bulk(reset){
 if(reset){
   const typed=prompt('CONTROLLED BULK PASSWORD RESET\n\nThe CURRENT signed-in Super Admin will be protected and kept unchanged. Other active users will receive new passwords.\n\nType RESET to continue:','');
   if(String(typed||'').trim().toUpperCase()!=='RESET')return;
 }
 const msg=q('#r146BulkMsg',mount);msg.style.display='block';msg.className='r146-statusbar warn';
 msg.textContent=reset?'Resetting other active users while protecting the signed-in Super Admin…':'Checking all users and creating only missing Auth logins…';
 try{
   const d=await edgeBulk({reset_existing:reset,mode:q('#r146BulkMode',mount).value,length:Number(q('#r146BulkLen',mount).value||8)});
   (d.credentials||[]).forEach(saveCred);
   if(d.credentials?.length)downloadCreds(d.credentials,reset?'OTHER_USERS_RESET':'MISSING_LOGINS');
   msg.className=d.failed_count?'r146-statusbar warn':'r146-statusbar good';
   const protectedMsg=d.current_admin_preserved?' · 1 CURRENT SUPER ADMIN PROTECTED':'';
   msg.innerHTML=`<b>BULK COMPLETE:</b> ${d.generated_count} generated · ${d.skipped_count} preserved/skipped · ${d.failed_count} failed${protectedMsg}.`;
   await load();
 }catch(e){
   const em=String(e&&e.message||e||'');msg.className='r146-statusbar bad';
   msg.innerHTML='<b>BULK ACTION FAILED:</b> '+esc(em)+( /refresh token|session|jwt|token.*not found|invalid.*token/i.test(em)?' <b>Re-login is required; do not run another bulk reset.</b>':'' );
 }
}
 q('#r146ACSearch',mount).oninput=filter;q('#r146ACRole',mount).onchange=filter;q('#r146ACLogin',mount).onchange=filter;q('#r146ACPer',mount).onchange=filter;q('#r146ACRefresh',mount).onclick=load;q('#r146ACPrint',mount).onclick=()=>{const pr=filtered.map(x=>({full_name:x.full_name,staff_code:x.staff_code,phone:x.phone,username:x.username,email:x.email,role_code:x.role_code,login_status:x.auth_user_id?'LOGIN READY':'NO AUTH LOGIN'}));printRows('USER ACCOUNTS DIRECTORY',[{key:'full_name',label:'FULL NAME'},{key:'staff_code',label:'STAFF CODE'},{key:'phone',label:'TELEPHONE'},{key:'username',label:'USERNAME'},{key:'email',label:'EMAIL'},{key:'role_code',label:'ROLE'},{key:'login_status',label:'LOGIN STATUS'}],pr)};q('#r146GenPass',mount).onclick=()=>q('#r146Password',mount).value=rand(q('#r146Len',mount).value,q('#r146Mode',mount).value);q('#r146GenUser',mount).onclick=async()=>{if(!selected)return;try{const d=await edge({action:'generate_username',profile_id:selected.profile_id});q('#r146Username',mount).value=d.username}catch(e){alert(e.message||e)}};q('#r146Save',mount).onclick=save;q('#r146SyncAll',mount).onclick=()=>bulk(false);q('#r146ResetAll',mount).onclick=()=>bulk(true);q('#r146CredDownload',mount).onclick=()=>downloadCreds(credSaved(),'SAVED_CREDENTIALS');q('#r146Directory',mount).onclick=()=>{const h=['FULL NAME','STAFF CODE','TELEPHONE','USERNAME','EMAIL','ROLE','LOGIN STATUS'],lines=[h.map(csvCell).join(',')].concat(filtered.map(x=>[x.full_name,x.staff_code,x.phone,x.username,x.email,x.role_code,x.auth_user_id?'LOGIN READY':'NO AUTH LOGIN'].map(csvCell).join(',')));download('GS_MUSUMBA_USER_DIRECTORY_'+new Date().toISOString().slice(0,10)+'.csv',lines.join('\n'))};q('#r146AddToggle',mount).onclick=()=>{const e=q('#r146Add',mount);e.style.display=e.style.display==='none'?'block':'none';if(e.style.display==='block')e.scrollIntoView({behavior:'smooth'})};q('#r146Create',mount).onclick=async()=>{const staff=q('#r146AddStaff',mount).value,msg=q('#r146AddMsg',mount);if(!staff){msg.textContent='Select staff first.';return}try{const customU=q('#r146AddUser',mount).value.trim(),customP=q('#r146AddPass',mount).value;const d=await edge({action:'create_user',staff_id:staff,role_code:q('#r146AddRole',mount).value,username:customU||undefined,generate_username:!customU,password:customP||undefined,generate_password:!customP,mode:q('#r146AddMode',mount).value,length:Number(q('#r146AddLen',mount).value||8)});saveCred(d);msg.innerHTML=`<b>USER CREATED:</b> ${esc(d.full_name)} · ${esc(d.username)}${d.temporary_password?` · <span class="r146-vault-secret">${esc(d.temporary_password)}</span>`:''}`;await load()}catch(e){msg.innerHTML='<b>CREATE FAILED:</b> '+esc(e.message||e)}};q('#r146VaultClear',mount).onclick=()=>{if(confirm('Clear saved plaintext temp credentials from this browser? Download them first.')){localStorage.removeItem(CRED);renderVault()}};load()};
V.r145_accounts=V.r146_accounts;V.r144_accounts=V.r146_accounts;V.r135_users=V.r146_accounts;V.r131_users=V.r146_accounts;V.r129_users=V.r146_accounts;V.users=V.r146_accounts;

// Make generic live_service route the three professional monitoring screens.
