function parseCsv(text){
 const rows=[];let row=[],cell='',q=false;
 for(let i=0;i<text.length;i++){const ch=text[i],nx=text[i+1];if(ch==='"'){if(q&&nx==='"'){cell+='"';i++}else q=!q}else if(ch===','&&!q){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&nx==='\n')i++;row.push(cell);cell='';if(row.some(x=>String(x).trim()!==''))rows.push(row);row=[]}else cell+=ch}
 row.push(cell);if(row.some(x=>String(x).trim()!==''))rows.push(row);if(!rows.length)return[];
 const keys=rows.shift().map(x=>String(x).trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''));
 return rows.map(r=>Object.fromEntries(keys.map((k,i)=>[k,String(r[i]??'').trim()]))).filter(x=>Object.values(x).some(Boolean));
}
function yesNo(v){if(v===true||String(v).toLowerCase()==='true'||String(v).toUpperCase()==='YES')return true;if(v===false||String(v).toLowerCase()==='false'||String(v).toUpperCase()==='NO')return false;return null}
function sexCode(s){s=upper(s);return s.startsWith('F')?'F':s.startsWith('M')?'M':s}
function time(t){return String(t||'').slice(0,5)}
function dayNo(d){return ({MONDAY:1,TUESDAY:2,WEDNESDAY:3,THURSDAY:4,FRIDAY:5})[upper(d)]||9}

