/* Full Student Profile — lifetime identity + annual history. */
const priorStudentProfile=V.studentprofile;
V.studentprofile=function(mount,ctx,params){
 const sdms=String(params&&params.sid||'').trim();if(!sdms){if(typeof priorStudentProfile==='function')return priorStudentProfile(mount,ctx,params);mount.innerHTML='<div class="t166-status bad">SDMS code required.</div>';return}
 mount.innerHTML=`<div class="t166-page">${head('FULL STUDENT PROFILE','Permanent identity · annual enrolment, attendance, marks and student welfare history')}<div id="t166ProfState" class="t166-status">Loading secure profile by SDMS…</div><div id="t166ProfBody"></div></div>`;
 let data=null;
 async function load(){try{data=await rpc('r166_student_full_profile_by_sdms',{p_sdms_code:sdms});$('#t166ProfState',mount).className='t166-status good';$('#t166ProfState',mount).innerHTML='<b>LIVE PROFILE LOADED.</b> SDMS and Student Name are master-locked. Missing identification fields do not block Submit.';draw()}catch(e){$('#t166ProfState',mount).className='t166-status bad';$('#t166ProfState',mount).innerHTML='<b>PROFILE LOAD FAILED:</b> '+esc(e&&e.message||e);$('#t166ProfBody',mount).innerHTML=''}}
 function inputField(id,label,val,type='text',disabled=false,wide=''){return `<div class="t166-field ${wide}"><label>${esc(label)}</label><input id="${id}" type="${type}" value="${esc(val||'')}" ${disabled?'disabled':''}></div>`}
 function draw(){
  const s=data.student||{},cur=data.current_enrolment||{},h=data.health||{},canI=!!(data.allowed_actions&&data.allowed_actions.edit_identification),canH=!!(data.allowed_actions&&data.allowed_actions.edit_health),missing=data.missing_profile_fields||[];
  $('#t166ProfBody',mount).innerHTML=`<div class="t166-profile-hero"><div class="t166-avatar">${esc(initials(s.full_name))}</div><div><h2>${esc(s.full_name||'')}</h2><p>SDMS ${esc(s.sdms_code||'')} · ${esc(cur.class_code||'NO CURRENT CLASS')} · ${esc(s.sex||'')}</p></div><div class="t166-profile-score"><b>${esc(s.completion_percent||0)}%</b><span>IDENTIFICATION COMPLETE</span></div></div>
  <div class="t166-status ${missing.length?'warn':'good'}">${missing.length?`<b>PROFILE STILL INCOMPLETE:</b> ${esc(missing.join(', '))}. Teacher may still save or submit.`:'<b>IDENTIFICATION COMPLETE.</b> Future verified changes remain part of the permanent audit history.'}</div>
  <div class="t166-tabs t166-no-print"><button class="t166-tab active" data-tab="identity">IDENTIFICATION</button><button class="t166-tab" data-tab="health">HEALTH & SPECIAL NEEDS</button><button class="t166-tab" data-tab="attendance">ATTENDANCE</button><button class="t166-tab" data-tab="marks">MARKS</button><button class="t166-tab" data-tab="history">ACADEMIC HISTORY</button><button class="t166-tab" data-tab="clubs">CLUBS</button></div>
  <div id="t166ProfTab"></div>`;
  function show(tab){
   const box=$('#t166ProfTab',mount); if(!box)return;
   if(tab==='identity'){
    box.innerHTML=`<div class="t166-panel"><div class="t166-panel-h"><div><h3>STUDENT IDENTIFICATION</h3><small>${canI?'Editable because you are the authorized Class Teacher / admin.':'Read-only in your current role/scope.'}</small></div><div class="t166-actions t166-no-print"><button class="t166-btn purple" id="t166ProfPrint">PRINT PROFILE</button>${canI?'<button class="t166-btn gold" id="t166ProfDraft">SAVE DRAFT</button><button class="t166-btn green" id="t166ProfSubmit">SUBMIT</button>':''}</div></div><div class="t166-panel-b"><div class="t166-profile-grid">
     ${inputField('t166PSdms','SDMS CODE',s.sdms_code,'text',true)}${inputField('t166PName','STUDENT NAME',s.full_name,'text',true)}${inputField('t166PSex','SEX',s.sex,'text',true)}
     ${inputField('t166PDob','DATE OF BIRTH',s.date_of_birth,'date',!canI)}${inputField('t166PAge','REPORTED AGE',s.reported_age,'number',!canI)}${inputField('t166PBoard','BOARDING / DAY',s.boarding_type,'text',!canI)}${inputField('t166PClass','CURRENT CLASS',cur.class_code||'NO CURRENT CLASS','text',true)}${inputField('t166PStatus','PROFILE STATUS',s.identification_status,'text',true)}
     ${inputField('t166PFName','FATHER / GUARDIAN NAME',s.father_guardian_name,'text',!canI)}${inputField('t166PFId','FATHER / GUARDIAN ID',s.father_guardian_id,'text',!canI)}${inputField('t166PFPhone','FATHER / GUARDIAN PHONE',s.father_guardian_phone,'tel',!canI)}
     ${inputField('t166PMName','MOTHER / GUARDIAN NAME',s.mother_guardian_name,'text',!canI)}${inputField('t166PMId','MOTHER / GUARDIAN ID',s.mother_guardian_id,'text',!canI)}${inputField('t166PMPhone','MOTHER / GUARDIAN PHONE',s.mother_guardian_phone,'tel',!canI)}
     ${inputField('t166PDistrict','DISTRICT',s.district,'text',!canI)}${inputField('t166PSector','SECTOR',s.sector,'text',!canI)}${inputField('t166PCell','CELL',s.cell,'text',!canI)}${inputField('t166PVillage','VILLAGE',s.village,'text',!canI)}
    </div></div></div>`;
    const pr=$('#t166ProfPrint',box); if(pr)pr.onclick=printProfile;
    if(canI){const dr=$('#t166ProfDraft',box),su=$('#t166ProfSubmit',box);if(dr)dr.onclick=()=>saveIdentity(false);if(su)su.onclick=()=>saveIdentity(true)}
    return;
   }
   if(tab==='health'){
    if(h.redacted){box.innerHTML='<div class="t166-status warn"><b>HEALTH DETAILS REDACTED.</b> Only the assigned Class Teacher and authorized welfare roles can view/edit disease and special-needs details.</div>';return}
    box.innerHTML=`<div class="t166-panel"><div class="t166-panel-h"><div><h3>HEALTH & SPECIAL NEEDS</h3><small>Sensitive information · controlled access.</small></div>${canH?'<div class="t166-actions t166-no-print"><button class="t166-btn gold" id="t166HDraft">SAVE DRAFT</button><button class="t166-btn green" id="t166HSubmit">SUBMIT</button></div>':''}</div><div class="t166-panel-b"><div class="t166-profile-grid">
     <div class="t166-field"><label>HAS ANY DISEASE?</label><select id="t166HDisease" ${canH?'':'disabled'}><option value="false" ${h.has_disease===false?'selected':''}>NO</option><option value="true" ${h.has_disease===true?'selected':''}>YES</option></select></div>
     ${inputField('t166HDiseaseType','DISEASE TYPE',h.disease_type,'text',!canH)}<div class="t166-field wide"><label>DISEASE DETAILS</label><textarea id="t166HDiseaseDetails" ${canH?'':'disabled'}>${esc(h.disease_details||'')}</textarea></div>
     <div class="t166-field"><label>HAS SPECIAL NEED?</label><select id="t166HSN" ${canH?'':'disabled'}><option value="false" ${h.has_special_need===false?'selected':''}>NO</option><option value="true" ${h.has_special_need===true?'selected':''}>YES</option></select></div>
     ${inputField('t166HSNType','SPECIAL NEED TYPE',h.special_need_type,'text',!canH)}${inputField('t166HImpair','IMPAIRMENT TYPE',h.impairment_type,'text',!canH)}${inputField('t166HSeverity','SEVERITY',h.severity,'text',!canH)}
     <div class="t166-field full"><label>CARE / SUPPORT NOTES</label><textarea id="t166HNotes" ${canH?'':'disabled'}>${esc(h.care_notes||'')}</textarea></div>
    </div></div></div>`;
    if(canH){const dr=$('#t166HDraft',box),su=$('#t166HSubmit',box);if(dr)dr.onclick=()=>saveHealth(false);if(su)su.onclick=()=>saveHealth(true)}
    return;
   }
   if(tab==='attendance'){
    const a=data.attendance_summary||{},ca=data.recent_class_attendance||[],sa=data.recent_subject_attendance||[];
    box.innerHTML=`<div class="t166-kpis"><div class="t166-kpi"><b>${fmt(a.class_total||0)}</b><span>CLASS ATT. ROWS</span></div><div class="t166-kpi green"><b>${fmt(a.present||0)}</b><span>PRESENT</span></div><div class="t166-kpi red"><b>${fmt(a.absent||0)}</b><span>ABSENT</span></div><div class="t166-kpi gold"><b>${fmt(a.late||0)}</b><span>LATE</span></div><div class="t166-kpi purple"><b>${fmt(a.follow_up_required||0)}</b><span>FOLLOW-UP</span></div></div><div class="t166-panel"><div class="t166-panel-h"><div><h3>RECENT CLASS ATTENDANCE</h3><small>Newest records first.</small></div></div><div class="t166-table-wrap" style="border:0;border-radius:0"><table class="t166-table"><thead><tr><th>DATE</th><th>CLASS</th><th>STATUS</th><th>REASON</th><th>TEACHER ADVICE</th></tr></thead><tbody>${ca.length?ca.map(x=>`<tr><td>${esc(x.attendance_date||'')}</td><td>${esc(x.class_code||'')}</td><td>${pill(x.attendance_status)}</td><td>${esc(x.reason||'—')}</td><td>${esc(x.teacher_advice||'—')}</td></tr>`).join(''):'<tr><td colspan="5"><div class="t166-empty">No class attendance history.</div></td></tr>'}</tbody></table></div></div><div class="t166-panel"><div class="t166-panel-h"><div><h3>RECENT SUBJECT ATTENDANCE</h3></div></div><div class="t166-table-wrap" style="border:0;border-radius:0"><table class="t166-table"><thead><tr><th>DATE</th><th>CLASS</th><th>SUBJECT</th><th>STATUS</th><th>REASON</th></tr></thead><tbody>${sa.length?sa.map(x=>`<tr><td>${esc(x.lesson_date||'')}</td><td>${esc(x.class_code||'')}</td><td>${esc(shortSub(x.subject_code,x.subject_name))} · ${esc(x.subject_name||'')}</td><td>${pill(x.attendance_status)}</td><td>${esc(x.reason||'—')}</td></tr>`).join(''):'<tr><td colspan="5"><div class="t166-empty">No subject attendance history.</div></td></tr>'}</tbody></table></div></div>`;
    return;
   }
   if(tab==='marks'){
    const ms=data.marks_summary||{},rr=data.recent_marks||[];
    box.innerHTML=`<div class="t166-kpis"><div class="t166-kpi"><b>${fmt(ms.assessment_rows||0)}</b><span>ASSESSMENTS</span></div><div class="t166-kpi"><b>${fmt(ms.mark_rows||0)}</b><span>MARK ROWS</span></div><div class="t166-kpi green"><b>${ms.average_percent==null?'—':esc(ms.average_percent)+'%'}</b><span>AVERAGE</span></div></div><div class="t166-panel"><div class="t166-table-wrap" style="border:0;border-radius:0"><table class="t166-table"><thead><tr><th>DATE</th><th>CLASS</th><th>SUBJECT</th><th>ASSESSMENT</th><th>MARK</th><th>MAX</th><th>%</th><th>STATUS</th></tr></thead><tbody>${rr.length?rr.map(x=>`<tr><td>${esc(x.assessment_date||'—')}</td><td>${esc(x.class_code||'')}</td><td>${esc(shortSub(x.subject_code,x.subject_name))}</td><td>${esc(x.assessment_name||'')}</td><td><b>${x.mark==null?'—':esc(x.mark)}</b></td><td>${esc(x.max_mark||'')}</td><td>${x.percentage==null?'—':esc(x.percentage)+'%'}</td><td>${pill(x.mark_status)}</td></tr>`).join(''):'<tr><td colspan="8"><div class="t166-empty">No marks recorded yet.</div></td></tr>'}</tbody></table></div></div>`;
    return;
   }
   if(tab==='history'){
    const rr=data.enrolment_history||[];box.innerHTML=`<div class="t166-panel"><div class="t166-panel-h"><div><h3>ACADEMIC YEAR / CLASS HISTORY</h3><small>Student Master remains one permanent record; annual enrolments form the history.</small></div></div><div class="t166-panel-b"><div class="t166-history">${rr.length?rr.map(x=>`<div class="t166-history-row"><b>${esc(x.academic_year||'')}</b><span>${esc(x.class_code||'')}</span><span>${pill(x.enrollment_status)} ${x.promotion_decision?' · '+esc(x.promotion_decision):''}</span></div>`).join(''):'<div class="t166-empty">No enrolment history is available yet.</div>'}</div></div></div>`;return;
   }
   if(tab==='clubs'){
    const rr=data.clubs||[];box.innerHTML=`<div class="t166-panel"><div class="t166-table-wrap" style="border:0;border-radius:0"><table class="t166-table"><thead><tr><th>ACADEMIC YEAR</th><th>CLUB</th><th>JOINED</th><th>STATUS</th></tr></thead><tbody>${rr.length?rr.map(x=>`<tr><td>${esc(x.academic_year||'')}</td><td><b>${esc(x.club_name||x.club_code||'')}</b></td><td>${esc(x.joined_at||'—')}</td><td>${pill(x.status)}</td></tr>`).join(''):'<tr><td colspan="4"><div class="t166-empty">No club membership recorded.</div></td></tr>'}</tbody></table></div></div>`;
   }
  }
  $$('.t166-tab',mount).forEach(b=>b.onclick=()=>{$$('.t166-tab',mount).forEach(x=>x.classList.remove('active'));b.classList.add('active');show(b.dataset.tab)});
  show('identity');
 }
 async function saveIdentity(submit){const s=data.student||{};const payload={sdms_code:s.sdms_code,full_name:s.full_name,date_of_birth:$('#t166PDob',mount).value||null,reported_age:$('#t166PAge',mount).value.trim(),boarding_type:$('#t166PBoard',mount).value.trim(),father_guardian_name:$('#t166PFName',mount).value.trim(),father_guardian_id:$('#t166PFId',mount).value.trim(),father_guardian_phone:$('#t166PFPhone',mount).value.trim(),mother_guardian_name:$('#t166PMName',mount).value.trim(),mother_guardian_id:$('#t166PMId',mount).value.trim(),mother_guardian_phone:$('#t166PMPhone',mount).value.trim(),district:$('#t166PDistrict',mount).value.trim(),sector:$('#t166PSector',mount).value.trim(),cell:$('#t166PCell',mount).value.trim(),village:$('#t166PVillage',mount).value.trim()};try{data=await rpc('r165_save_student_identification',{p_student_id:s.id,p_payload:payload,p_submit:submit});alert(submit?'Student identification submitted. Missing fields, if any, remain open for future update.':'Student identification draft saved.');draw()}catch(e){alert(String(e&&e.message||e))}}
 async function saveHealth(submit){const s=data.student||{};const payload={has_disease:$('#t166HDisease',mount).value==='true',disease_type:$('#t166HDiseaseType',mount).value.trim(),disease_details:$('#t166HDiseaseDetails',mount).value.trim(),has_special_need:$('#t166HSN',mount).value==='true',special_need_type:$('#t166HSNType',mount).value.trim(),impairment_type:$('#t166HImpair',mount).value.trim(),severity:$('#t166HSeverity',mount).value.trim(),care_notes:$('#t166HNotes',mount).value.trim()};try{data=await rpc('r165_save_student_health',{p_student_id:s.id,p_payload:payload,p_submit:submit});alert(submit?'Health / Special Needs information submitted.':'Health / Special Needs draft saved.');draw();const hb=$('.t166-tab[data-tab="health"]',mount);if(hb){$$('.t166-tab',mount).forEach(x=>x.classList.remove('active'));hb.classList.add('active');const ev=new Event('click');hb.dispatchEvent(ev)}}catch(e){alert(String(e&&e.message||e))}}
 function printProfile(){const s=data.student||{},cur=data.current_enrolment||{},h=data.health||{},area=$('#printArea');if(!area)return window.print();area.innerHTML=(window.GSM_buildLetterhead?window.GSM_buildLetterhead('STUDENT IDENTIFICATION PROFILE',s.full_name+' — SDMS '+s.sdms_code,context().ay,context().term):'')+`<h2 style="text-align:center;margin:8px 0">STUDENT IDENTIFICATION PROFILE</h2><table><tbody>
  <tr><td><b>SDMS CODE</b></td><td>${esc(s.sdms_code||'')}</td><td><b>STUDENT NAME</b></td><td>${esc(s.full_name||'')}</td></tr>
  <tr><td><b>SEX</b></td><td>${esc(s.sex||'')}</td><td><b>CURRENT CLASS</b></td><td>${esc(cur.class_code||'NO CURRENT CLASS')}</td></tr>
  <tr><td><b>DATE OF BIRTH</b></td><td>${esc(s.date_of_birth||'—')}</td><td><b>REPORTED AGE</b></td><td>${esc(s.reported_age||'—')}</td></tr><tr><td><b>BOARDING / DAY</b></td><td>${esc(s.boarding_type||'—')}</td><td><b>PROFILE COMPLETE</b></td><td>${esc(s.completion_percent||0)}%</td></tr>
  <tr><td><b>FATHER / GUARDIAN</b></td><td>${esc(s.father_guardian_name||'—')}</td><td><b>PHONE</b></td><td>${esc(s.father_guardian_phone||'—')}</td></tr>
  <tr><td><b>MOTHER / GUARDIAN</b></td><td>${esc(s.mother_guardian_name||'—')}</td><td><b>PHONE</b></td><td>${esc(s.mother_guardian_phone||'—')}</td></tr>
  <tr><td><b>ADDRESS</b></td><td colspan="3">${esc([s.district,s.sector,s.cell,s.village].filter(Boolean).join(' / ')||'—')}</td></tr>
  ${h.redacted?'':`<tr><td><b>DISEASE</b></td><td>${h.has_disease?'YES · '+esc(h.disease_type||''):'NO / NOT RECORDED'}</td><td><b>SPECIAL NEED</b></td><td>${h.has_special_need?'YES · '+esc(h.special_need_type||''):'NO / NOT RECORDED'}</td></tr>`}
  </tbody></table>`+(window.GSM_buildSignatures?window.GSM_buildSignatures():'');window.print()}
 load();
};

/* My attendance: read-only self service. */
V.teachermyattendance=function(mount,ctx){
 let rows=[];const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1),iso=d=>d.toISOString().slice(0,10);
 mount.innerHTML=`<div class="t166-page">${head('MY ATTENDANCE','Read-only staff attendance for the signed-in teacher')}<div class="t166-panel"><div class="t166-panel-b"><div class="t166-toolbar"><label>FROM<input id="t166MAFrom" type="date" value="${iso(first)}"></label><label>TO<input id="t166MATo" type="date" value="${today()}"></label><button class="t166-btn primary" id="t166MALoad">REFRESH</button><button class="t166-btn purple" id="t166MAPrint">PRINT</button><button class="t166-btn green" id="t166MADownload">DOWNLOAD</button></div></div></div><div id="t166MAState" class="t166-status">Loading your attendance…</div><div id="t166MABody"></div></div>`;
 const cols=[{key:'attendance_date',label:'DATE'},{key:'arrival_time',label:'ARRIVAL'},{key:'departure_time',label:'DEPARTURE'},{key:'attendance_status',label:'STATUS'},{key:'reason',label:'REASON'}];
 function draw(){const present=rows.filter(x=>upper(x.attendance_status)==='PRESENT').length,late=rows.filter(x=>upper(x.attendance_status)==='LATE').length,abs=rows.filter(x=>upper(x.attendance_status)==='ABSENT').length;$('#t166MABody',mount).innerHTML=`<div class="t166-kpis"><div class="t166-kpi"><b>${rows.length}</b><span>RECORDS</span></div><div class="t166-kpi green"><b>${present}</b><span>PRESENT</span></div><div class="t166-kpi gold"><b>${late}</b><span>LATE</span></div><div class="t166-kpi red"><b>${abs}</b><span>ABSENT</span></div></div><div class="t166-table-wrap"><table class="t166-table"><thead><tr><th>DATE</th><th>ARRIVAL</th><th>DEPARTURE</th><th>STATUS</th><th>REASON</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><b>${esc(x.attendance_date||'')}</b></td><td>${esc(time(x.arrival_time)||'—')}</td><td>${esc(time(x.departure_time)||'—')}</td><td>${pill(x.attendance_status)}</td><td>${esc(x.reason||'—')}</td></tr>`).join(''):'<tr><td colspan="5"><div class="t166-empty">No attendance rows in this date range.</div></td></tr>'}</tbody></table></div>`}
 async function load(){try{const d=await rpc('r165_my_staff_attendance',{p_from:$('#t166MAFrom',mount).value||null,p_to:$('#t166MATo',mount).value||null});rows=d.rows||[];$('#t166MAState',mount).className='t166-status good';$('#t166MAState',mount).innerHTML='<b>READ-ONLY SELF ATTENDANCE.</b> DOD / authorized administration remains attendance authority.';draw()}catch(e){$('#t166MAState',mount).className='t166-status bad';$('#t166MAState',mount).textContent=String(e&&e.message||e)}}
 $('#t166MALoad',mount).onclick=load;$('#t166MAPrint',mount).onclick=()=>printRows('MY STAFF ATTENDANCE','Signed-in teacher attendance',cols,rows,false);$('#t166MADownload',mount).onclick=()=>downloadCsv('GS_MUSUMBA_MY_ATTENDANCE.csv',cols,rows);load();
};


