/* Absentee Follow-up */
V.teacherabsenteefollowup=function(mount,ctx){
 const c=context();let classes=[],rows=[];
 mount.innerHTML=`<div class="t166-page">${head('ABSENTEE FOLLOW-UP','Click a student name to open the Full Student Profile immediately')}<div class="t166-panel"><div class="t166-panel-b"><div class="t166-toolbar"><label>CLASS<select id="t166AFClass"><option value="">ALL AUTHORIZED CLASSES</option></select></label><label>FROM<input id="t166AFFrom" type="date"></label><label>TO<input id="t166AFTo" type="date" value="${today()}"></label><label class="search">SEARCH<input id="t166AFSearch" placeholder="Student, SDMS, parent or telephone"></label><label>SORT<select id="t166AFSort"><option value="LAST_ABSENCE_DESC">LAST ABSENCE</option><option value="ABSENT_COUNT_DESC">ABSENT COUNT</option><option value="EVENT_COUNT_DESC">ALL EXCEPTIONS</option><option value="NAME_ASC">NAME A–Z</option></select></label><button class="t166-btn primary" id="t166AFGo">REFRESH</button><button class="t166-btn purple" id="t166AFPrint">PRINT</button><button class="t166-btn green" id="t166AFDownload">DOWNLOAD</button></div></div></div><div id="t166AFState" class="t166-status">Loading absentee follow-up…</div><div id="t166AFBody"></div></div>`;
 const cols=[{key:'sdms_code',label:'SDMS'},{key:'full_name',label:'STUDENT'},{key:'class_code',label:'CLASS'},{key:'last_absence_date',label:'LAST EVENT'},{key:'absent_count',label:'ABSENT'},{key:'late_count',label:'LATE'},{key:'event_count',label:'ALL EVENTS'},{key:'completion_percent',label:'PROFILE %'},{key:'father_guardian_phone',label:'PARENT PHONE'}];
 function render(){$('#t166AFBody',mount).innerHTML=`<div class="t166-table-wrap"><table class="t166-table"><thead><tr><th>NO.</th>${cols.map(c=>'<th>'+esc(c.label)+'</th>').join('')}<th>ACTION</th></tr></thead><tbody>${rows.length?rows.map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.sdms_code||'')}</b></td><td><button class="t166-link" data-af-profile="${esc(x.sdms_code||'')}">${esc(x.full_name||'')}</button></td><td><b>${esc(x.class_code||'')}</b></td><td>${esc(x.last_absence_date||'—')}</td><td>${fmt(x.absent_count||0)}</td><td>${fmt(x.late_count||0)}</td><td>${fmt(x.event_count||0)}</td><td><b>${esc(x.completion_percent||0)}%</b></td><td>${esc(x.father_guardian_phone||x.mother_guardian_phone||'—')}</td><td><button class="t166-btn primary" data-af-profile="${esc(x.sdms_code||'')}">FULL PROFILE</button></td></tr>`).join(''):'<tr><td colspan="11"><div class="t166-empty">No absentee / exception records match the selected period.</div></td></tr>'}</tbody></table></div>`;$$('[data-af-profile]',mount).forEach(b=>b.onclick=()=>openProfile(ctx,b.dataset.afProfile))}
 async function load(){try{const d=await rpc('r166_teacher_absentee_followup',{p_academic_year_id:c.ayId,p_term_id:c.termId,p_class_id:$('#t166AFClass',mount).value||null,p_from:$('#t166AFFrom',mount).value||null,p_to:$('#t166AFTo',mount).value||null,p_search:$('#t166AFSearch',mount).value.trim()||null,p_sort:$('#t166AFSort',mount).value,p_limit:1101,p_offset:0});rows=d.rows||[];if(!$('#t166AFFrom',mount).value&&d.from_date)$('#t166AFFrom',mount).value=d.from_date;$('#t166AFState',mount).className='t166-status good';$('#t166AFState',mount).innerHTML=`<b>${fmt(d.total||rows.length)} student(s) require follow-up in the selected period.</b> Open a name to view profile, contacts, attendance and profile completeness.`;render()}catch(e){$('#t166AFState',mount).className='t166-status bad';$('#t166AFState',mount).textContent=String(e&&e.message||e);rows=[];render()}}
 rpc('r167_teacher_dashboard',{p_academic_year_id:c.ayId,p_term_id:c.termId}).then(d=>{classes=d.classes||[];$('#t166AFClass',mount).innerHTML='<option value="">ALL AUTHORIZED CLASSES</option>'+classes.map(x=>`<option value="${esc(x.class_id)}">${esc(x.class_code)}</option>`).join('');load()}).catch(()=>load());
 $('#t166AFGo',mount).onclick=load;$('#t166AFSearch',mount).onkeydown=e=>{if(e.key==='Enter')load()};['t166AFClass','t166AFSort'].forEach(id=>$('#'+id,mount).onchange=load);$('#t166AFPrint',mount).onclick=()=>printRows('ABSENTEE FOLLOW-UP REPORT','Teacher authorized scope',cols,rows,true);$('#t166AFDownload',mount).onclick=()=>downloadCsv('GS_MUSUMBA_ABSENTEE_FOLLOWUP.csv',cols,rows);
};

/* My Club & Members */
V.teachermyclub=function(mount,ctx){
 const c=context();let clubs=[];
 mount.innerHTML=`<div class="t166-page">${head('MY CLUB & MEMBERS','Only clubs where you are the assigned patron')}<div class="t166-panel"><div class="t166-panel-b"><div class="t166-toolbar"><label class="search">SEARCH MEMBERS<input id="t166ClubSearch" placeholder="Student name, SDMS, parent or phone"></label><button class="t166-btn primary" id="t166ClubGo">REFRESH</button><button class="t166-btn purple" id="t166ClubPrint">PRINT</button><button class="t166-btn green" id="t166ClubDownload">DOWNLOAD</button></div></div></div><div id="t166ClubState" class="t166-status">Loading assigned clubs…</div><div id="t166ClubBody"></div></div>`;
 function render(){$('#t166ClubBody',mount).innerHTML=clubs.length?`<div class="t166-club-grid">${clubs.map(cl=>`<div class="t166-club"><div class="t166-club-h"><h3>${esc(cl.club_name||cl.club_code||'CLUB')}</h3><p>${esc(cl.activity_day||'—')} · ${esc(cl.activity_time||'—')} · ${fmt(cl.member_count||0)} members</p></div><div class="t166-table-wrap" style="border:0;border-radius:0"><table class="t166-table" style="min-width:620px"><thead><tr><th>NO.</th><th>SDMS</th><th>STUDENT NAME</th><th>SEX</th><th>CLASS</th></tr></thead><tbody>${(cl.members||[]).map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.sdms_code||'')}</b></td><td><button class="t166-link" data-club-profile="${esc(x.sdms_code||'')}">${esc(x.student_name||'')}</button></td><td>${esc(sexCode(x.sex))}</td><td><b>${esc(x.class_code||'NO CURRENT CLASS')}</b></td></tr>`).join('')||'<tr><td colspan="5"><div class="t166-empty">No active club members.</div></td></tr>'}</tbody></table></div></div>`).join('')}</div>`:'<div class="t166-status warn"><b>NO CLUB ASSIGNMENT:</b> This teacher is not currently assigned as patron of an active club.</div>';$$('[data-club-profile]',mount).forEach(b=>b.onclick=()=>openProfile(ctx,b.dataset.clubProfile))}
 async function load(){try{const d=await rpc('r166_teacher_club_workspace',{p_academic_year_id:c.ayId,p_search:$('#t166ClubSearch',mount).value.trim()||null});clubs=d.rows||[];$('#t166ClubState',mount).className='t166-status good';$('#t166ClubState',mount).innerHTML='<b>'+fmt(d.count||clubs.length)+' assigned club(s) loaded.</b>';render()}catch(e){$('#t166ClubState',mount).className='t166-status bad';$('#t166ClubState',mount).textContent=String(e&&e.message||e);clubs=[];render()}}
 const flat=()=>clubs.flatMap(cl=>(cl.members||[]).map(x=>({...x,club_name:cl.club_name||cl.club_code})));
 const cols=[{key:'club_name',label:'CLUB'},{key:'sdms_code',label:'SDMS'},{key:'student_name',label:'STUDENT'},{key:'sex',label:'SEX'},{key:'class_code',label:'CLASS'}];
 $('#t166ClubGo',mount).onclick=load;$('#t166ClubSearch',mount).onkeydown=e=>{if(e.key==='Enter')load()};$('#t166ClubPrint',mount).onclick=()=>printRows('MY CLUB & MEMBERS','Teacher club patron roster',cols,flat(),true);$('#t166ClubDownload',mount).onclick=()=>downloadCsv('GS_MUSUMBA_MY_CLUB_MEMBERS.csv',cols,flat());load();
};

