/* ---------- R186.8 DOD / SUPER ADMIN CANONICAL DASHBOARD ---------- */
const previousDashboard=V.dashboard;

function dashPct(v){v=Number(v||0);return Math.max(0,Math.min(100,Number.isFinite(v)?v:0))}
function dashBar(label,value,max,tone){const n=Number(value||0),m=Math.max(1,Number(max||1)),w=Math.max(n>0?3:0,Math.min(100,Math.round(n/m*100)));return '<div class="r1868-bar '+(tone||'')+'"><label>'+esc(label)+'</label><div class="r1868-track"><i style="--w:'+w+'%"></i></div><strong>'+fmt(n)+'</strong></div>'}
function dashStat(value,label,tone,sub){return '<article class="r1868-stat '+(tone||'blue')+'"><b>'+esc(value)+'</b><span>'+esc(label)+'</span>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</article>'}
function renderDashboardR1868(mount,ctx){
 const crumb=q('#crumb');if(crumb)crumb.textContent='GS MUSUMBA DASHBOARD';
 mount.innerHTML='<div class="r1868-dash"><div class="r170-status">Loading live GS MUSUMBA dashboard…</div></div>';
 window.GSM_R1866_REFRESH_DASH=()=>renderDashboardR1868(mount,ctx);
 Promise.all([
   rpc('r171_school_dashboard',{p_anchor_date:localDate()}),
   rpc('r170_academic_monitoring_cards',{}).catch(()=>({live_status:{}}))
 ]).then(([d,acad])=>{
   const k=d&&d.kpis||{},att=d&&d.attendance||{},mk=d&&d.marks||{},levels=d&&d.population_by_level||[],missing=(d&&d.missing_updates||[]).filter(x=>Number(x&&x.count||0)>0);
   const maxPop=Math.max(1,...levels.map(x=>Number(x.students||0)));
   const attLive=upper(att.state)==='LIVE',attPct=attLive?dashPct(att.attendance_pct):0;
   const markTotal=Math.max(1,Number(mk.complete||0)+Number(mk.partial||0)+Number(mk.not_started||0));
   const markPct=dashPct(((Number(mk.complete||0)+Number(mk.partial||0)*.5)/markTotal)*100);
   const attentionCount=missing.length;
   const bars=['NURSERY','PRIMARY','SECONDARY'].map((name,i)=>{const x=levels.find(a=>upper(a.level)===name)||{};return dashBar(name,Number(x.students||0),maxPop,i===0?'purple':i===2?'green':'')}).join('');
   const alerts=missing.slice(0,4).map(x=>'<div class="r1868-alert '+(upper(x.severity)==='HIGH'?'red':'')+'"><span><b>'+esc(x.title||'Attention')+'</b><small>'+esc(x.action||'Review required')+'</small></span><strong>'+fmt(x.count)+'</strong></div>').join('')||'<div class="r1868-alert"><span><b>NO CRITICAL EXCEPTION</b><small>Current live dashboard has no unresolved exception in the returned scope.</small></span><strong>✓</strong></div>';
   const actions=[['r131_sa_dod','DOD','Attendance & discipline'],['r131_sa_dos','DOS','Academics & marks'],['r131_sa_tch','TEACHERS','Teacher workspace'],['r131_sa_stu','STUDENTS','Student records'],['r131_sa_sys','SYSTEM','Management & QA'],['r131_sa_reports','REPORTS','Official outputs']];
   const s=acad&&acad.live_status||{};
   mount.innerHTML='<div class="r1868-dash">'+
    '<section class="r1868-rail">'+
      dashStat(fmt(k.current_students),'STUDENTS','blue','Active enrolment')+
      dashStat(fmt(k.teachers),'TEACHERS','purple','Teaching staff')+
      dashStat(fmt(k.staff),'ALL STAFF','teal','Current staff')+
      dashStat(attLive?Number(att.attendance_pct||0).toFixed(1)+'%':'NOT STARTED','ATTENDANCE',attLive?'green':'gold',attLive?'Today':'Term starts '+esc(att.term_start_date||''))+
      dashStat(markPct.toFixed(0)+'%','ACADEMIC READY',markPct>=80?'green':markPct>=50?'gold':'red',fmt(mk.marks_entered)+' marks entered')+
      dashStat(fmt(attentionCount),'ATTENTION','red',fmt(k.live_services)+' live services')+
    '</section>'+
    '<section class="r1868-grid">'+
      '<article class="r1868-panel"><div class="r1868-head"><b>STUDENT POPULATION</b><span>Live enrolment by level</span></div><div class="r1868-bars">'+bars+'</div></article>'+
      '<article class="r1868-panel"><div class="r1868-head"><b>SCHOOL HEALTH TODAY</b><span>Attendance + academic workflow</span></div><div class="r1868-health"><div class="r1868-ring" style="--pct:'+attPct+';--ring:'+(attLive?'#16834a':'#d29a00')+'"><div><b>'+(attLive?attPct.toFixed(1)+'%':'—')+'</b><span>'+(attLive?'ATTENDANCE':'TERM NOT STARTED')+'</span></div></div><div class="r1868-health-list"><div class="r1868-health-row"><span>Class attendance complete</span><b>'+fmt(att.complete||0)+'</b></div><div class="r1868-health-row"><span>Classes partial / pending</span><b>'+fmt(Number(att.partial||0)+Number(att.not_done||0))+'</b></div><div class="r1868-health-row"><span>Academic readiness</span><b>'+markPct.toFixed(0)+'%</b></div><div class="r1868-health-row"><span>Assigned teachers</span><b>'+fmt(s.assigned_teachers||k.teachers||0)+'</b></div></div></div></article>'+
    '</section>'+
    '<section class="r1868-bottom"><article class="r1868-panel"><div class="r1868-head"><b>ACTION / ATTENTION</b><span>Only items requiring follow-up</span></div><div class="r1868-alerts">'+alerts+'</div></article><article class="r1868-panel"><div class="r1868-head"><b>QUICK COMMANDS</b><span>Open the operational workspace directly</span></div><div class="r1868-actions">'+actions.map(a=>'<button class="r1868-action" data-r1868-go="'+a[0]+'"><b>'+a[1]+'</b><span>'+a[2]+'</span></button>').join('')+'</div></article></section>'+
    '<section class="r1868-preview"><div><b>ROLE DASHBOARD PREVIEW</b><span>Teacher · DOS · Headteacher dashboards are reviewed from Super Admin without changing the signed-in account.</span></div><div class="r1868-preview-buttons"><button type="button" data-r1868-preview="TEACHER">TEACHER</button><button type="button" data-r1868-preview="DOS">DOS</button><button type="button" data-r1868-preview="HEADTEACHER">HEADTEACHER</button></div></section>'+
   '</div>';
   qa('[data-r1868-go]',mount).forEach(b=>b.onclick=()=>{const x=q('.side-link[data-id="'+b.dataset.r1868Go+'"]');if(x)x.click()});
   qa('[data-r1868-preview]',mount).forEach(b=>b.onclick=()=>{const key=b.dataset.r1868Preview;alert(key+' dashboard preview will open after its role dashboard QA is finalized. Current signed-in account remains DOD / SUPER ADMIN.')});
 }).catch(e=>{mount.innerHTML='<div class="r1868-dash"><div class="r170-status bad"><b>DASHBOARD FAILED:</b> '+esc(e&&e.message||e)+'</div></div>'});
}

