function ensureBackProxy(){
  const focus=$('.gsm-r168-focusbar');
  const oldBack=focus&&$('.gsm-r168-back',focus);
  let b=$('#r175ServiceBack');
  if(!focus || !oldBack){if(b)b.remove();return;}
  if(!b){
    b=document.createElement('button');b.id='r175ServiceBack';b.type='button';b.textContent='←';b.title='Back to previous service';b.setAttribute('aria-label','Back to previous service');
    const burger=$('#burger'),left=$('#topbar .tb-left');
    if(left){ if(burger&&burger.nextSibling)left.insertBefore(b,burger.nextSibling); else left.prepend(b); }
  }
  b.onclick=()=>{const x=$('.gsm-r168-focusbar .gsm-r168-back');if(x)x.click();};
}
function enforceMobileTopbar(){
  const t=$('#topbar');if(!t)return;
  const props=['height','min-height','display','flex-direction','align-items','justify-content','padding','gap','overflow'];
  if(window.innerWidth<=600){
    const v={'height':'76px','min-height':'76px','display':'flex','flex-direction':'column','align-items':'stretch','justify-content':'flex-start','padding':'4px 6px','gap':'4px','overflow':'hidden'};
    Object.entries(v).forEach(([k,val])=>t.style.setProperty(k,val,'important'));
  }else{
    props.forEach(k=>t.style.removeProperty(k));
  }
}
function syncFocusTitle(){
  enforceMobileTopbar();
  const focus=$('.gsm-r168-focusbar');
  if(focus){
    const title=norm($('.gsm-r168-focus-title b',focus)?.textContent);
    if(title)setTitle(title);
  }else{
    const a=$('.side-link.active');
    if(a)setTitle(norm(a.textContent));
  }
  ensureBackProxy();
  hideDuplicateTitle();
}
function hideDuplicateTitle(){
  const title=up($('#crumb')?.textContent);if(!title)return;
  const heads=$$('#main .page-head h1,#main .page-head h2,#main .r172-head h2,#main .r170-head h2,#main .r132-head h2,#main .r131-sub-head h3');
  heads.forEach(h=>{
    if(up(h.textContent)!==title)return;
    const parent=h.parentElement;
    if(parent && !parent.querySelector('button,a,input,select'))parent.classList.add('r175-duplicate-title-block');
    else h.classList.add('r175-duplicate-title-block');
  });
}

