function wireDash(mount,ctx,preview){$$('[data-r186x-go]',mount).forEach(x=>x.onclick=()=>{if(!preview)go(x.dataset.r186xGo,ctx)});$$('[data-r186x-preview]',mount).forEach(x=>x.onclick=()=>{const v=x.dataset.r186xPreview;if(v==='ADMIN')return renderAdminDashboard(mount,ctx,false);if(v==='TEACHER')return renderTeacherDashboard(mount,ctx,true);if(v==='DOS')return renderDOSDashboard(mount,ctx,true);if(v==='HEADTEACHER')return renderHTDashboard(mount,ctx,true);if(v==='DOD')return renderDODDashboard(mount,ctx,true)});animateDash(mount)}
