function renderAdminDashboard(mount,ctx,preview=false){
 const live=window.GSM_LIVE;if(!live||typeof live.rpc!=='function')return;
 const dashToken=beginDashRender(mount);
 mount.className=(mount.className||'').replace(/\\br186x-[^\\s]+/g,'').trim();
 mount.classList.add('r186x-mount','r186x-admin-theme');
 try{const c=document.getElementById('crumb');if(c)c.textContent='GS MUSUMBA DASHBOARD';document.title='GS MUSUMBA DASHBOARD | GS MUSUMBA SCHOOL MANAGEMENT SYSTEM'}catch(_){ }
 mount.innerHTML='<div class="r186x-loading">Loading live school dashboard…</div>';
 live.rpc('r18635_school_dashboard',{p_anchor_date:kDate()}).then(d=>{
   if(!dashRenderAlive(mount,dashToken))return;
   const k=d.kpis||{},att=d.attendance||{},mk=d.marks||{},
     attention=(d.missing_updates||[]).filter(x=>n(x.count)>0).length,
     actions=[
       ['r132_sa_ht','HEADTEACHER','Leadership oversight, approvals and evidence','H'],
       ['r132_sa_dos','DOS ACADEMICS','Marks, timetable and academic readiness','A'],
       ['r132_sa_dod','DOD OPERATIONS','Attendance, discipline, welfare and movement','D'],
       ['r132_sa_sec','SECRETARY','Administration, records and official documents','S'],
       ['r132_sa_bur','BURSAR','Finance, payments and school financial records','$'],
       ['r132_sa_tch','TEACHERS','Teacher readiness, workload and services','T'],
       ['r132_sa_stu','STUDENTS','Student records, enrolment and profiles','ST'],
       ['r132_sa_sys','SYSTEM MANAGEMENT','Security, health, setup and QA','⚙'],
       ['r18638_sa_lib','LIBRARIAN','Books, inventory, issue, return and overdue control','L']
     ],
     attVal=String(att.state||'').toUpperCase()==='LIVE'?n(att.attendance_pct):'—';
   mount.innerHTML=
     quick(actions,false)+
     '<section class="r186x-preview-panel"><div><b>ROLE DASHBOARD PREVIEW</b><span>View each role dashboard without changing the signed-in account.</span></div><div class="r186x-preview-actions"><button data-r186x-preview="TEACHER">TEACHER</button><button data-r186x-preview="DOS">DOS</button><button data-r186x-preview="HEADTEACHER">HEADTEACHER</button><button data-r186x-preview="DOD">DOD</button></div></section>'+
     '<div class="r186x-kpis">'+
       metric(n(k.current_students),'CURRENT STUDENTS',{icon:'S',tone:'blue',go:'r132_sa_stu'})+
       metric(attVal,'ATTENDANCE TODAY',{icon:'✓',tone:String(att.state||'').toUpperCase()==='LIVE'?'green':'amber',suffix:typeof attVal==='number'?'%':'',decimals:1,sub:String(att.state||''),go:'r132_sa_dod'})+
       metric(n(k.teachers),'TEACHERS',{icon:'T',tone:'purple',go:'r132_sa_tch'})+
       metric(n(k.live_services),'LIVE SERVICES',{icon:'●',tone:'green',go:'r132_sa_sys'})+
       metric(n(mk.marks_entered),'MARKS ENTERED',{icon:'M',tone:'blue',go:'r132_sa_dos'})+
       metric(attention,'ATTENTION AREAS',{icon:'!',tone:attention?'red':'green',go:'r132_sa_dod'})+
     '</div>'+
     '<div class="r186x-grid-main">'+
       populationBars(d)+
       bars('SCHOOL ATTENDANCE','Live attendance completion by level',((att&&att.level_summary)||[]).map(x=>({label:x.level||'LEVEL',value:n(x.completion_pct),display:n(x.completion_pct).toFixed(1)+'% complete',tone:n(x.completion_pct)>=95?'green':n(x.completion_pct)>=70?'amber':'red'})),{max:100})+
     '</div>'+
     alerts(schoolAlerts(d,'r132_sa_dod'),false)+footerDash();
   wireDash(mount,ctx,false);
 }).catch(e=>dashError(mount,'GS MUSUMBA dashboard could not load.',e,()=>renderAdminDashboard(mount,ctx,false)));
}
function installRoleDashboards(){
 const V=window.GSM_VIEWS,live=window.GSM_LIVE;
 if(!V||!live||typeof live.rpc!=='function')return false;
 if(!window.GSM_R186_DASHBOARD_FALLBACK)window.GSM_R186_DASHBOARD_FALLBACK=V.dashboard;
 if(V.dashboard&&V.dashboard.__gsmR1865Final)return true;
 const fallback=window.GSM_R186_DASHBOARD_FALLBACK;
 const finalDashboard=function(mount,ctx){
   window.__GSM_LAST_CTX__=ctx||window.__GSM_LAST_CTX__||null;
   const r=role();
   if(r==='TEACHER')return renderTeacherDashboard(mount,ctx,false);
   if(r==='DOS')return renderDOSDashboard(mount,ctx,false);
   if(r==='HEADTEACHER'||r==='HEAD_TEACHER')return renderHTDashboard(mount,ctx,false);
   if(r==='SUPER_ADMIN')return renderAdminDashboard(mount,ctx,false);
   if(r==='DOD')return renderDODDashboard(mount,ctx,false);
   return typeof fallback==='function'?fallback(mount,ctx):undefined;
 };
 finalDashboard.__gsmR1865Final=true;
 
 window.GSM_R1865_DASHBOARD=finalDashboard;
 return true;
}
function dashboardIsOpen(){
 const st=window.__GSM_LAST_CTX__&&window.__GSM_LAST_CTX__.state;
 const item=st&&st.currentItem;
 if(item&&item.view)return String(item.view).toLowerCase()==='dashboard';
 const active=document.querySelector('.side-link.active');
 return !!(active&&/dashboard/i.test(String(active.textContent||'')));
}
function renderCurrentDashboardNow(){
 if(!dashboardIsOpen()||!installRoleDashboards())return false;
 const mount=document.getElementById('main'); if(!mount)return false;
 const currentFinal=!!mount.querySelector('.r186x-hero,.r186x-preview-panel,.r186x-kpis');
 const old=/SCHOOL STUDENTS LIVE|EXECUTIVE DASHBOARD|ATTENDANCE INTELLIGENCE|MARKS\s*\/\s*ACADEMIC READINESS/i.test(mount.textContent||'');
 if(currentFinal&&!old)return true;
 try{window.GSM_R1865_DASHBOARD(mount,window.__GSM_LAST_CTX__||null);return true}catch(_){return false}
}
function armDashboardAuthority(){
 let tries=0;
 const tick=()=>{
   const installed=installRoleDashboards();
   const rendered=installed&&renderCurrentDashboardNow();
   if((!installed||!rendered)&&++tries<20)setTimeout(tick,150);
 };
 tick();
 document.addEventListener('click',ev=>{
   const el=ev.target&&ev.target.closest&&ev.target.closest('.side-link');
   if(el&&/dashboard/i.test(el.textContent||''))setTimeout(()=>{installRoleDashboards();renderCurrentDashboardNow()},35);
 },false);
 const main=document.getElementById('main');
 if(main){[100,300,800].forEach(ms=>setTimeout(()=>{if(dashboardIsOpen()&&!main.querySelector('.r18652-teacher-hero,.r186x-hero'))renderCurrentDashboardNow()},ms));}
}

