const R1867_HEADER_SHORT={
 'PERIODS/WEEK':'PERIODS / WEEK','REQUIRED / WEEK':'REQUIRED / WEEK',
 'PARENT TELEPHONE':'PARENT TELEPHONE','LAST ABSENT DATE':'LAST ABSENT DATE'
};
function r1867HeaderTone(text){const t=String(text||'').toUpperCase();
 /* Meaning first: ABSENT must remain red and PRESENT green even when BOYS/GIRLS is also in the label. */
 if(/ABSENT|NOT DONE|MISSING|FAILED|CRITICAL|REJECT|ERROR|BLOCK/.test(t))return'negative';
 if(/PARTIAL|PENDING|LATE|EXCEPTION|UNRECORDED|WARNING|RISK/.test(t))return'warning';
 if(/PRESENT|COMPLETE|READY|RECORDED|PASSED|APPROVED|SUCCESS/.test(t))return'positive';
 if(/ENROL|TOTAL|EXPECTED/.test(t))return'total';
 if(/BOY/.test(t))return'boys'; if(/GIRL/.test(t))return'girls';
 if(/STATUS|ACTION|CHECK|REMARK|DECISION/.test(t))return'action';
 if(/STUDENT|TEACHER|CLASS|SUBJECT|STAFF|NAME/.test(t))return'total';
 return'default';
}
function enhanceTables(root=document){
 const scope=root&&root.querySelectorAll?root:document;
 scope.querySelectorAll('#appShell table').forEach(table=>{
   table.classList.add('r1867-fit-table');
   const colCount=table.querySelectorAll('thead th').length;
   table.classList.toggle('r18611-dense-table',colCount>10);
   table.classList.toggle('r18611-ultradense-table',colCount>15);
   const wrap=table.closest('.tbl-wrap,.r170-table-wrap,.r148-tablewrap,.r169-tablewrap,.r172-table-wrap,.r1852-table-wrap,.imh-table-wrap,.r135-table-wrap,.r1869-tablewrap,[class*="table-wrap"],[class*="tablewrap"]');
   if(wrap)wrap.classList.add('r1867-fit-wrap');
   table.querySelectorAll('thead th').forEach(th=>{
     if(!th.dataset.r1867Original)th.dataset.r1867Original=(th.textContent||'').trim();
     const original=th.dataset.r1867Original.toUpperCase().replace(/\s+/g,' ').trim();
     const short=R1867_HEADER_SHORT[original];
     if(short&&th.textContent.trim()!==short)th.textContent=short;
     const tone=r1867HeaderTone(original);th.dataset.r1867Tone=tone;
     if(/NAME|STUDENT|TEACHER|SUBJECT|REASON|COMMENT|DESCRIPTION|SERVICE/.test(original))th.classList.add('r1867-wide');
     if(/^(NO|#|SEX|CLASS|LEVEL)$/.test(original))th.classList.add('r1867-narrow');
   });
 });
}
