window.GSM_FINAL_VIEW_RESOLVER=function(mount,uiCtx,it,params){
  const dep=U(it?.department||params?.department||'');
  const view=String(it?.view||'');
  const label=U(it?.label||'');

  /* R186.25 NAVIGATION BARRIER
     Cancel every pending dashboard render before any non-dashboard service opens.
     This prevents a late dashboard RPC from repainting the service page. */
  if(view.toLowerCase()!=='dashboard'){
    const guard=window.GSM_R186_DASHBOARD_GUARD;
    if(guard&&typeof guard.cancel==='function')guard.cancel(mount);
    else if(mount)mount.dataset.r186DashToken='r18627-cancel-'+Date.now()+'-'+Math.random().toString(36).slice(2);
    if(guard&&typeof guard.clearTheme==='function')guard.clearTheme(mount);
    else if(mount){
      mount.className=(mount.className||'').split(/\s+/).filter(c=>c&&!/^r186x-/.test(c)).join(' ');
      mount.removeAttribute('data-r18625-workspace');
    }
  }

  /* Explicit owner workspaces. Later inherited scripts redefine some r133_* views,
     so route them here to the canonical department map instead of allowing a stale renderer. */
  const explicitRoleViews={
    r133_headteacher:'HEADTEACHER',r128_sa_ht:'HEADTEACHER',r129_sa_ht:'HEADTEACHER',r131_sa_ht:'HEADTEACHER',
    r133_dos:'DOS',r128_sa_dos:'DOS',r129_sa_dos:'DOS',r131_sa_dos:'DOS',
    r133_secretary:'SECRETARY',r128_sa_sec:'SECRETARY',r129_sa_sec:'SECRETARY',r131_sa_sec:'SECRETARY',
    r133_bursar:'BURSAR',r128_sa_bur:'BURSAR',r129_sa_bur:'BURSAR',r131_sa_bur:'BURSAR',
    r133_system:'SYSTEM',r128_sa_sys:'SYSTEM',r129_sa_sys:'SYSTEM',r131_sa_sys:'SYSTEM'
  };
  const labelRole={HEADTEACHER:'HEADTEACHER',DOS:'DOS',SECRETARY:'SECRETARY',BURSAR:'BURSAR','SYSTEM MANAGEMENT':'SYSTEM'};
  const ownerRole=explicitRoleViews[view]||labelRole[label]||'';
  if(ownerRole&&typeof V.r132_department==='function'){
    NAV.rootId=it.id;NAV.rootCtx=uiCtx;NAV.stack=[];NAV.current=null;
    setTopTitle(it.label||ownerRole);
    if(mount)mount.dataset.r18625Workspace=ownerRole.toLowerCase();
    V.r132_department(mount,uiCtx,{department:ownerRole});
    return true;
  }

  /* DOD is a hard final owner. Do not fall back into legacy department routing. */
  if(view==='r153_dod'||view==='r133_dod'||view==='r118_dod_workspace'||(view==='departmenthub'&&dep==='DOD')||(label==='DOD'&&['SUPER_ADMIN','DOD'].includes(activeRole()))){
    if(mount)mount.dataset.r18625Workspace='dod';
    return r18619OpenDod(mount,uiCtx,it);
  }
  /* Other department workspaces use the canonical R132 owner map. */
  if(view==='departmenthub'&&typeof V.r132_department==='function'){
    const roleKey=U(it.department||params?.department||it.label||'WORKSPACE');
    NAV.rootId=it.id;NAV.rootCtx=uiCtx;NAV.stack=[];NAV.current=null;setTopTitle(it.label||it.department||'WORKSPACE');
    if(mount)mount.dataset.r18625Workspace=roleKey.toLowerCase().replace(/\s+/g,'-');
    V.r132_department(mount,uiCtx,{department:it.department||params?.department||it.label});return true;
  }
  const r=directCritical(it);if(r&&typeof r[1]==='function'){
    NAV.rootId=uiCtx?.prevId||it.id;NAV.rootCtx=uiCtx;NAV.stack=[];NAV.current={title:r[0],type:'direct'};return serviceShell(r[0],r[1],uiCtx,params||{});
  }
  return false;
};

