    const cleanNode=root=>{if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){if(!n.nodeValue)continue;let v=n.nodeValue;v=v.replace(/DOD\s*\/\s*SUPER\s+ADMIN\s+COMMAND\s+CENTER/gi,'GS MUSUMBA DASHBOARD');v=v.replace(/Live school operations, academics, attendance and system attention\.?/gi,'');v=v.replace(/GS\s+MUSUMBA\s+SCHOOL\s+MANAGEMENT\s+SYSTEM/gi,'GS MUSUMBA');v=v.replace(/SCHOOL\s+MANAGEMENT\s+SYSTEM/gi,'');if(v!==n.nodeValue)n.nodeValue=v}};
    cleanNode(app);
    if(app){[80,350].forEach(ms=>setTimeout(()=>cleanNode(app),ms));document.addEventListener('click',()=>setTimeout(()=>cleanNode(app),50),true)}
