  mount.innerHTML='<div class="r18629-page r18629-lessons"><section class="r18629-pagehead"><div><h2>LESSON PLANS</h2><p>Create, save draft and submit lesson plans for your assigned classes and subjects.</p></div><button id="r18629LpRefresh" type="button">REFRESH</button></section><div id="r18629LpSummary" class="r18629-summary"></div><section class="r18629-formcard"><div class="r18629-formtitle"><b>NEW LESSON PLAN</b><span>Only your assigned class/subject combinations are available.</span></div><div class="r18629-formgrid"><label class="full">CLASS / SUBJECT<select id="r18629LpAssign"></select></label><label>LESSON DATE<input id="r18629LpDate" type="date"></label><label>LESSON TITLE<input id="r18629LpTitle" placeholder="Lesson title"></label><label class="full">LESSON OBJECTIVE<textarea id="r18629LpObjective" rows="2"></textarea></label><label class="full">CONTENT SUMMARY<textarea id="r18629LpContent" rows="3"></textarea></label><label class="full">LEARNING ACTIVITIES<textarea id="r18629LpActivities" rows="3"></textarea></label><label>ASSESSMENT METHOD<input id="r18629LpAssess"></label><label>REMEDIAL PLAN<input id="r18629LpRemedial"></label><label class="full">EVIDENCE / REFERENCE<input id="r18629LpEvidence" placeholder="Optional URL or reference"></label></div><div class="r18629-actions"><button id="r18629LpDraft" class="secondary" type="button">SAVE DRAFT</button><button id="r18629LpSubmit" class="primary" type="button">SUBMIT PLAN</button></div></section><section class="r18629-listcard"><div class="r18629-formtitle"><b>MY LESSON PLANS</b><span id="r18629LpCount">Loading…</span></div><div id="r18629LpRows"></div></section></div>';
  const e=id=>$('#'+id,mount);const today=()=>{const d=new Date(),z=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate())};e('r18629LpDate').value=today();
