V.r18636_staff_meeting_list=function(mount){pageTitle('STAFF MEETING / TRAINING ATTENDANCE LIST');let rows=[],filtered=[];mount.innerHTML=`<div class="r18636-panel"><h3>STAFF MEETING / TRAINING ATTENDANCE LIST</h3><div class="r18636-tools-row r18636-no-print"><label>SEARCH<input id="r18636StaffSearch" placeholder="Name, staff code, phone, email, role"></label><label>ROLE<select id="r18636StaffRole"><option value="">ALL ROLES</option></select></label><label>SORT<select id="r18636StaffSort"><option value="NAME">NAME A–Z</option><option value="CODE">STAFF CODE</option><option value="ROLE">ROLE</option></select></label><button id="r18636StaffPrint" class="r18636-btn-blue">PRINT ATTENDANCE LIST</button><button id="r18636StaffRefresh" class="r18636-btn-white">REFRESH</button></div><div id="r18636StaffState" class="r18636-marks-status">LOADING ACTIVE STAFF…</div></div><div class="r18636-table-wrap"><table><thead><tr><th class="r18636-col-no">NO.</th><th class="r18636-col-sdms">STAFF / SDMS CODE</th><th class="r18636-col-name">STAFF NAME</th><th class="r18636-col-sex">SEX</th><th>TELEPHONE</th><th>EMAIL</th><th>ROLE</th><th>SIGNATURE</th></tr></thead><tbody id="r18636StaffRows"></tbody></table></div>`;const e=id=>$('#'+id,mount);function draw(){const q=e('r18636StaffSearch').value.toLowerCase(),rr=up(e('r18636StaffRole').value),s=e('r18636StaffSort').value;filtered=rows.filter(x=>(!q||[x.full_name,x.staff_code,x.phone,x.email,x.job_title].join(' ').toLowerCase().includes(q))&&(!rr||up(x.job_title)===rr));filtered.sort((a,b)=>s==='CODE'?String(a.staff_code||'').localeCompare(String(b.staff_code||''),undefined,{numeric:true}):s==='ROLE'?String(a.job_title||'').localeCompare(String(b.job_title||''))||String(a.full_name||'').localeCompare(String(b.full_name||'')):String(a.full_name||'').localeCompare(String(b.full_name||'')));e('r18636StaffState').textContent='SHOWING '+filtered.length+' OF '+rows.length+' ACTIVE STAFF';e('r18636StaffRows').innerHTML=filtered.map((x,i)=>'<tr><td>'+(i+1)+'</td><td><b>'+esc(x.staff_code||'')+'</b></td><td class="name">'+esc(x.full_name||'')+'</td><td>'+mf(x.sex)+'</td><td>'+esc(x.phone||'—')+'</td><td>'+esc(x.email||'—')+'</td><td><b>'+esc(up(x.job_title||'STAFF'))+'</b></td><td class="r18636-signature"></td></tr>').join('')||'<tr><td colspan="8">No staff match.</td></tr>'}
 async function load(){e('r18636StaffState').textContent='LOADING ACTIVE STAFF…';try{rows=(await L.table('staff','*')).filter(x=>up(x.status)==='ACTIVE');const roles=[...new Set(rows.map(x=>up(x.job_title)).filter(Boolean))].sort();e('r18636StaffRole').innerHTML='<option value="">ALL ROLES</option>'+roles.map(x=>'<option>'+esc(x)+'</option>').join('');draw()}catch(x){e('r18636StaffState').textContent='ERROR: '+err(x)}}
 e('r18636StaffSearch').oninput=draw;e('r18636StaffRole').onchange=draw;e('r18636StaffSort').onchange=draw;e('r18636StaffRefresh').onclick=load;e('r18636StaffPrint').onclick=()=>{const rs=filtered.map((x,i)=>({no:i+1,code:x.staff_code||'',name:x.full_name||'',sex:mf(x.sex),phone:x.phone||'',email:x.email||'',role:up(x.job_title||'STAFF'),signature:''}));window.GSM_printReport({title:'STAFF MEETING / TRAINING ATTENDANCE LIST',subTitle:'GS MUSUMBA · '+new Date().toLocaleDateString(),ay:ctx().ay,term:ctx().term,columns:[{key:'no',label:'NO.'},{key:'code',label:'STAFF / SDMS CODE'},{key:'name',label:'STAFF NAME'},{key:'sex',label:'SEX'},{key:'phone',label:'TELEPHONE'},{key:'email',label:'EMAIL'},{key:'role',label:'ROLE'},{key:'signature',label:'SIGNATURE'}],rows:rs,landscape:true})};load()};

