V.r18636_conduct_marks=function(mount){pageTitle('CONDUCT MARKS');let rows=[],filtered=[],selected=null;mount.innerHTML=`<div class="r18636-panel"><h3>CONDUCT MARKS · EVENT-DRIVEN</h3><p>Each offence is recorded as its own transaction. The system counts offences, totals deductions and calculates remaining marks automatically from 40.</p><div class="r18636-tools-row r18636-no-print"><label>CLASS<select id="r18636ConClass"><option value="">ALL CLASSES</option></select></label><label>SEARCH<input id="r18636ConSearch" placeholder="Student or SDMS"></label><label>SORT<select id="r18636ConSort"><option value="NAME">NAME</option><option value="LOW">LOWEST REMAINING</option><option value="OFFENCES">MOST OFFENCES</option></select></label><button id="r18636ConPrint" class="r18636-btn-blue">PRINT</button><button id="r18636ConRefresh" class="r18636-btn-white">REFRESH</button></div><div id="r18636ConState" class="r18636-marks-status">LOADING CONDUCT SUMMARY…</div></div><div class="r18636-table-wrap"><table><thead><tr><th class="r18636-col-no">NO.</th><th class="r18636-col-sdms">SDMS CODE</th><th class="r18636-col-name">STUDENT NAME</th><th class="r18636-col-sex">SEX</th><th class="r18636-col-class">CLASS</th><th>START MARK</th><th>NO. OF OFFENCES</th><th>POINTS DEDUCTED</th><th>ADDITIONS</th><th>REMAINING MARKS</th><th class="r18636-col-status">STATUS</th><th class="r18636-col-remark">DECISION</th><th class="r18636-col-action">ACTION</th></tr></thead><tbody id="r18636ConRows"></tbody></table></div><form id="r18636ConEditor" class="r18636-panel r18636-no-print" hidden><h3 id="r18636ConTitle">RECORD CONDUCT</h3><div class="r18636-form-row"><label>TYPE<select id="r18636ConType"><option value="NEGATIVE">OFFENCE / DEDUCTION</option><option value="POSITIVE">POSITIVE / ADDITION</option></select></label><label>CATEGORY<input id="r18636ConCategory" required></label><label>DESCRIPTION / REASON<input id="r18636ConDesc" required></label><label>POINTS<input id="r18636ConPoints" type="number" min="0.01" step="0.01" required></label><button class="r18636-btn-green" type="submit">SAVE EVENT</button></div><button type="button" id="r18636ConCancel" class="r18636-btn-white">CANCEL</button></form>`;const e=id=>$('#'+id,mount);function tone(x){return up(x.status)==='CRITICAL'?'r18636-status-red':up(x.status).includes('ATTENTION')?'r18636-status-yellow':'r18636-status-green'}function draw(){const q=e('r18636ConSearch').value.toLowerCase(),cid=e('r18636ConClass').value,sort=e('r18636ConSort').value;filtered=rows.filter(x=>(!q||String(x.student_name).toLowerCase().includes(q)||String(x.sdms_code).toLowerCase().includes(q))&&(!cid||String(x.class_id)===cid));filtered.sort((a,b)=>sort==='LOW'?Number(a.remaining_marks)-Number(b.remaining_marks):sort==='OFFENCES'?Number(b.offence_count)-Number(a.offence_count):String(a.student_name).localeCompare(String(b.student_name)));e('r18636ConRows').innerHTML=filtered.map((x,i)=>'<tr><td>'+(i+1)+'</td><td><b>'+esc(x.sdms_code)+'</b></td><td class="name">'+esc(x.student_name)+'</td><td>'+mf(x.sex)+'</td><td><b>'+esc(x.class_code)+'</b></td><td>40</td><td><b>'+esc(x.offence_count)+'</b></td><td class="raw-check">'+esc(x.deductions)+'</td><td>'+esc(x.additions)+'</td><td class="official"><b>'+esc(x.remaining_marks)+'</b></td><td><span class="'+tone(x)+'">'+esc(x.status)+'</span></td><td>'+esc(x.decision)+'</td><td><button class="r18636-btn-red" data-offence="'+esc(x.student_id)+'">− OFFENCE</button><button class="r18636-btn-green" data-reward="'+esc(x.student_id)+'">+ REWARD</button></td></tr>').join('')||'<tr><td colspan="13">No students in scope.</td></tr>';$$('[data-offence]',mount).forEach(b=>b.onclick=()=>open(rows.find(x=>String(x.student_id)===b.dataset.offence),'NEGATIVE'));$$('[data-reward]',mount).forEach(b=>b.onclick=()=>open(rows.find(x=>String(x.student_id)===b.dataset.reward),'POSITIVE'))}
 function open(x,type){selected=x;e('r18636ConEditor').hidden=false;e('r18636ConType').value=type;e('r18636ConTitle').textContent=(type==='NEGATIVE'?'RECORD OFFENCE: ':'RECORD POSITIVE BEHAVIOUR: ')+x.student_name;e('r18636ConCategory').value='';e('r18636ConDesc').value='';e('r18636ConPoints').value='';e('r18636ConEditor').scrollIntoView({behavior:'smooth',block:'center'})}
 async function load(){e('r18636ConState').textContent='LOADING CONDUCT SUMMARY…';try{const d=await rpc('r18636_conduct_marks_summary',{p_class_id:null});rows=d.rows||[];const cls=[...new Map(rows.map(x=>[String(x.class_id),x])).values()];e('r18636ConClass').innerHTML='<option value="">ALL CLASSES</option>'+cls.map(x=>'<option value="'+esc(x.class_id)+'">'+esc(x.class_code)+'</option>').join('');e('r18636ConState').textContent=rows.length+' STUDENT(S) · TERM START MARK 40 · EACH OFFENCE IS AN AUDITED TRANSACTION';draw()}catch(x){e('r18636ConState').textContent='ERROR: '+err(x)}}
 e('r18636ConClass').onchange=draw;e('r18636ConSearch').oninput=draw;e('r18636ConSort').onchange=draw;e('r18636ConRefresh').onclick=load;e('r18636ConCancel').onclick=()=>e('r18636ConEditor').hidden=true;e('r18636ConEditor').onsubmit=async ev=>{ev.preventDefault();if(!selected)return;const p=Number(e('r18636ConPoints').value);if(!Number.isFinite(p)||p<=0)return;try{await rpc('r127_save_conduct_transaction',{p_payload:{student_id:selected.student_id,transaction_type:e('r18636ConType').value,category:e('r18636ConCategory').value,points:p,description:e('r18636ConDesc').value,transaction_date:new Date().toISOString().slice(0,10)}});e('r18636ConEditor').hidden=true;toast('Conduct event saved.');await load()}catch(x){alert(err(x))}};e('r18636ConPrint').onclick=()=>window.GSM_printReport({title:'CONDUCT MARKS SUMMARY',subTitle:'EVENT-BASED CONDUCT · START MARK 40',ay:ctx().ay,term:ctx().term,columns:[{key:'no',label:'NO.'},{key:'sdms',label:'SDMS CODE'},{key:'name',label:'STUDENT NAME'},{key:'sex',label:'SEX'},{key:'class',label:'CLASS'},{key:'offences',label:'NO. OF OFFENCES'},{key:'deducted',label:'POINTS DEDUCTED'},{key:'remaining',label:'REMAINING MARKS'},{key:'status',label:'STATUS'},{key:'decision',label:'DECISION'}],rows:filtered.map((x,i)=>({no:i+1,sdms:x.sdms_code,name:x.student_name,sex:mf(x.sex),class:x.class_code,offences:x.offence_count,deducted:x.deductions,remaining:x.remaining_marks,status:x.status,decision:x.decision})),landscape:true});load()};

