function addItem(dept,groupName,item){const d=D[dept];if(!d)return;let g=(d.groups||[]).find(x=>x.name===groupName);if(!g){g={name:groupName,items:[]};d.groups.push(g)}if(!(g.items||[]).some(x=>x.title===item.title))g.items.push(item)}
addItem('STUDENTS','Student Records',{title:'Student List Change / Upload / Save',desc:'Synchronize NO., SDMS CODE, STUDENT NAME and SEX by SDMS without overwriting full profiles or enrolments.',mode:'view',view:'r18636_student_roster_sync',icon:'↻'});
addItem('SECRETARY','Master Data',{title:'Student List Change / Upload / Save',desc:'Synchronize the minimal student roster while preserving identification profile details.',mode:'view',view:'r18636_student_roster_sync',icon:'↻'});
addItem('SYSTEM','Identity & School Setup',{title:'Staff Meeting / Training List',desc:'Filter, sort and print active staff attendance/signature lists for meetings or training.',mode:'view',view:'r18636_staff_meeting_list',icon:'T'});
addItem('DOS','Academic Planning',{title:'Staff Attendance',desc:'Record or update official daily staff attendance when DOS is responsible.',mode:'view',view:'r127_staff_attendance',icon:'✓'});
try{(D.DOD&&D.DOD.groups||[]).forEach(g=>(g.items||[]).forEach(it=>{if(/CONDUCT/i.test(it.title||'')||up(it.key)==='DOD_CONDUCT'){it.mode='view';it.view='r18636_conduct_marks';delete it.key;it.title='Conduct Marks';it.desc='Event-based offences, deductions, remaining marks, status and decisions.'}}))}catch(_){ }

