/* ========================= TIMETABLE COLOR AUTHORITY ========================= */
function subjectTone(text){const t=up(text);if(!t||t==='—')return'';if(/CONFLICT|ERROR|INVALID/.test(t))return'red';if(/\b(MATH|SET|SCI|SCIENCE|ICT|PHYS|CHEM|BIO)\b/.test(t))return'blue';if(/\b(ENG|ENGLISH|KINY|KINYARWANDA|FRE|FRENCH|SWAH|SWAHILI|LANG|LIT)\b/.test(t))return'green';if(/\b(SRE|REL|RELIG|HIST|GEOG|SOC|CIVIC|ENT)\b/.test(t))return'yellow';if(/\b(PES|PE\b|HOME SCI|CREATIVE|ART|MUSIC|DANCE|SPORT|CCA|CPD|ITORERO|UMUGANDA|ASSEMBLY|HYGIENE|BREAK|LUNCH)\b/.test(t))return'white';return'blue'}
function r18668SubjectKey(text){
 const t=up(text);
 if(/\b(MATH|MATHEMATICS)\b/.test(t))return'math';
 if(/\b(ENG|ENGLISH)\b/.test(t))return'english';
 if(/\b(KINY|KINYARWANDA)\b/.test(t))return'kiny';
 if(/\b(FRE|FRENCH)\b/.test(t))return'french';
 if(/\b(SWAH|SWAHILI)\b/.test(t))return'swahili';
 if(/\b(SET|SCI|SCIENCE|BIO|CHEM|PHYS)\b/.test(t))return'science';
 if(/\b(HIST|HISTORY)\b/.test(t))return'history';
 if(/\b(GEO|GEOG|GEOGRAPHY)\b/.test(t))return'geography';
 if(/\b(SRE|REL|RELIG|SOCIAL|CIVIC)\b/.test(t))return'sre';
 if(/\b(ENT|ENTREPRENEUR)\b/.test(t))return'ent';
 if(/\b(ICT|COMPUT)\b/.test(t))return'ict';
 if(/\b(PES|PE\b|SPORT)\b/.test(t))return'pes';
 if(/\b(HOME SCI|HOME SCIENCE)\b/.test(t))return'home';
 if(/\b(CREATIVE|ART|MUSIC|DANCE)\b/.test(t))return'arts';
 if(/\b(ASSEMBLY|HYGIENE)\b/.test(t))return'assembly';
 if(/\b(BREAK|LUNCH)\b/.test(t))return'break';
 if(/\b(CPD|CLUB|CCA|ITORERO|UMUGANDA)\b/.test(t))return'activity';
 return'general';
}
function colorTimetables(root=document){
 const targets=$$('.r18628-week tbody td:not(.empty),.r176-lesson,.r18629-today button span,.r186-today-row span:nth-child(3),.r186x-time-row span:last-child',root);
 targets.forEach(x=>{
   const txt=x.textContent||'',tone=subjectTone(txt),key=r18668SubjectKey(txt);
   if(tone)x.classList.add('r18636-subject-'+tone);
   if(key)x.classList.add('r18668-subject-'+key);
   x.dataset.r18636Color='1';
   if(!/^(TD|TH)$/.test(x.tagName))x.classList.add('r18636-tt-cell');
 });
}

/* Generic status colors for Attendance / Marks Monitoring / workflows. */
function colorStatuses(root=document){$$('#main table td',root).forEach(td=>{if(td.dataset.r18636Status==='1')return;const t=up(td.textContent);let cl='';if(/^(PRESENT|COMPLETE|COMPLETED|SUBMITTED|VERIFIED|APPROVED|ACTIVE|DONE)$/.test(t))cl='r18636-status-green';else if(/^(LATE|PENDING|PARTIAL|DRAFT|WARNING|PAY ATTENTION)$/.test(t))cl='r18636-status-yellow';else if(/^(ABSENT|MISSING|RETURNED|CRITICAL|ERROR|FAILED|INVALID)$/.test(t))cl='r18636-status-red';if(cl){td.dataset.r18636Status='1';td.classList.add(cl)}})}
let scheduled=false;function enhance(){scheduled=false;colorTimetables(document);colorStatuses(document)}
window.GSM_R18652_STATUS_ENHANCE=enhance;requestAnimationFrame(enhance);[180,700].forEach(ms=>setTimeout(enhance,ms));document.addEventListener('click',e=>{if(e.target.closest('button,.side-link'))setTimeout(enhance,40)},true);

