/* ===== R186.62 SMART TABLE AUTHORITY ===== */
(function(){'use strict';
 if(window.__GSM_R18662_TABLE_AUTHORITY__)return;window.__GSM_R18662_TABLE_AUTHORITY__=true;
 const qs=(s,r=document)=>r.querySelector(s),qsa=(s,r=document)=>Array.from(r.querySelectorAll(s));
 const norm=s=>String(s||'').replace(/\s+/g,' ').trim().toUpperCase();
 const NAME_RE=/(^|\b)(STUDENT NAME|FULL NAME|TEACHER(?:'S)? NAME|STAFF NAME|CLASS TEACHER|PARENT|GUARDIAN|MOTHER|FATHER|BORROWER|BOOK TITLE|TITLE|NAME)(\b|$)/;
 const CODE_RE=/(SDMS|STAFF CODE|BOOK CODE|ACCESSION|USERNAME|EMAIL)/;
 const COMPACT_RE=/^(NO\.?|#|SEX|GRADE|RANK|# ASS\.?|ASSESSMENTS? DONE|NO\. OF ASSESSMENTS?|NUMBER OF ASSESSMENTS?|TOTAL RAW|PERIODS?\/?WEEK|BOYS|GIRLS|PRESENT|ABSENT|MISSING|DAYS?|WEEK|TERM)$/;
 const PERCENT_RE=/(%|PERCENT|PCT)$/;
 function leafHeaders(t){const rows=t.tHead?Array.from(t.tHead.rows):[];return rows.length?Array.from(rows[rows.length-1].cells):[]}
 function wrapHeader(th){if(th.querySelector(':scope > .r18662-th-text'))return;const txt=th.textContent.trim();if(!txt)return;while(th.firstChild)th.removeChild(th.firstChild);const s=document.createElement('span');s.className='r18662-th-text';s.textContent=txt;th.appendChild(s)}
 function columnCells(t,i){const out=[];for(const tr of Array.from(t.tBodies||[]).flatMap(b=>Array.from(b.rows))){if(tr.cells&&tr.cells[i])out.push(tr.cells[i])}return out}
 function numericCompact(cells){let seen=0;for(const c of cells.slice(0,40)){let v=norm(c.textContent).replace(/[, ]/g,'');if(!v||v==='—'||v==='-'||v==='N/A')continue;seen++;if(!/^\d{1,3}(?:\.\d+)?%?$/.test(v))return false}return seen>=2}
 function markCol(t,i,cls){const rows=Array.from(t.rows||[]);for(const tr of rows){const c=tr.cells&&tr.cells[i];if(c)c.classList.add(cls)}}
 function enhanceTable(t){if(!t||!t.tHead)return;
   /* R186.65: complex Marks Entry has its own 17-column authority. The generic
      smart-table auto-layout was collapsing SDMS/name and expanding summary columns. */
   if(t.matches&&t.matches('.r18652-marks-entry,.r18650-marks-entry')){t.classList.remove('r18662-smart-table');return}
   t.classList.add('r18662-smart-table');const ths=leafHeaders(t);if(!ths.length)return;
   ths.forEach((th,i)=>{wrapHeader(th);const label=norm(th.textContent);const cells=columnCells(t,i);
     let cls='';
     if(NAME_RE.test(label)&&!CODE_RE.test(label))cls='r18662-name-col';
     else if(CODE_RE.test(label))cls='r18662-code-col';
     else if(PERCENT_RE.test(label))cls='r18662-percent-col';
     else if(COMPACT_RE.test(label)||numericCompact(cells))cls='r18662-compact-col';
     if(cls)markCol(t,i,cls);
   });
 }
 function enhance(root){qsa('table',root||document).forEach(enhanceTable)}
 let queued=0;function schedule(root){if(queued)return;queued=1;requestAnimationFrame(()=>{queued=0;enhance(root||qs('#main')||document)})}
 window.GSM_R18662_enhanceTables=enhance;
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>schedule(document));else schedule(document);
 document.addEventListener('click',e=>{if(e.target.closest('.side-link,[data-go],[data-r132],[data-r37-card],[data-r38-service],[data-st],[data-sm]'))setTimeout(()=>schedule(qs('#main')||document),25)},true);
 document.addEventListener('change',e=>{if(e.target.matches('#globalYear,#globalTerm'))setTimeout(()=>schedule(e.target.closest('#main')||qs('#main')||document),20)},true);
 window.addEventListener('hashchange',()=>setTimeout(()=>schedule(qs('#main')||document),15));
 try{document.documentElement.setAttribute('data-gsm-release','R186.66')}catch(_){}
})();


