function validate(rows){const seen=new Set();return rows.map(r=>{let error='';if(!/^\d{8,15}$/.test(r.sdms_code))error='Invalid or missing SDMS code';else if(seen.has(r.sdms_code))error='Duplicate SDMS code in file';else if(r.sex&& !['MALE','FEMALE'].includes(r.sex))error='Invalid SEX';seen.add(r.sdms_code);return Object.assign({},r,{local_status:error?'INVALID':'READY',local_message:error})})}
