 b.onclick=()=>{root.classList.add('r18652-center-open');host.hidden=false;host.innerHTML='<div class="r18652-service-backbar"><button type="button" data-r18663-back>← BACK TO SERVICES</button><b>'+esc(title)+'</b></div><div class="r18652-center-service-body"></div>';const body=$('.r18652-center-service-body',host);viewFn(body,ctx);const back=$('[data-r18663-back]',host);if(back)back.onclick=()=>{root.classList.remove('r18652-center-open');host.hidden=true;host.innerHTML=''};host.scrollIntoView({behavior:'auto',block:'start'})};
