function empty(msg='No current records.'){return '<div class="r18674-empty">'+esc(msg)+'</div>'}
function classGenderRows(rows){
 const a=(rows||[]).map(r=>({class_code:r.class_code||r.class_name||'—',boys:num(r.male!=null?r.male:r.boys),girls:num(r.female!=null?r.female:r.girls),total:num(r.total)}));
 a.forEach(x=>{if(!x.total)x.total=x.boys+x.girls});
 return a.sort((x,y)=>{const rank=s=>{const c=upper(s);if(c.startsWith('N'))return 0;if(c.startsWith('P'))return 100;if(c.startsWith('S'))return 200;return 300};return rank(x.class_code)-rank(y.class_code)||String(x.class_code).localeCompare(String(y.class_code),undefined,{numeric:true})})
}
function genderHistogram(rows){const a=classGenderRows(rows),max=Math.max(1,...a.map(x=>Math.max(x.boys,x.girls)));if(!a.length)return empty('Class population will appear when authorised enrolment data is available.');return '<div class="r18674-gender-legend"><span><i class="boys"></i>BOYS</span><span><i class="girls"></i>GIRLS</span></div><div class="r18674-gender-grid">'+a.map(x=>'<div class="r18674-gender-row"><strong>'+esc(x.class_code)+'</strong><div class="r18674-dual"><div><i class="boys" style="width:'+Math.max(x.boys?4:0,(x.boys/max)*100)+'%"></i><em>'+fmt(x.boys)+'</em></div><div><i class="girls" style="width:'+Math.max(x.girls?4:0,(x.girls/max)*100)+'%"></i><em>'+fmt(x.girls)+'</em></div></div><b>'+fmt(x.total)+'</b></div>').join('')+'</div>'}
