function attendanceRows(raw){return(raw||[]).map(r=>{const enrolled=num(r.enrolled_total),boys=num(r.enrolled_boys),girls=num(r.enrolled_girls),pb=num(r.present_boys),pg=num(r.present_girls),ab=num(r.absent_boys),ag=num(r.absent_girls);return{level:upper(r.level)||levelOf(r.class_code),class_code:r.class_code||'—',enrolled,boys,girls,pb,pg,ab,ag,present:pb+pg,absent:ab+ag,status:upper(r.completion_status||r.status)}})}
