function performanceTable(title,rows){if(!rows.length)return '<div class="r18674-perf-box"><h4>'+esc(title)+'</h4>'+empty('No valid performance result is available for this selection.')+'</div>';return '<div class="r18674-perf-box"><h4>'+esc(title)+'</h4><table class="r18674-table performance"><thead><tr><th>NO.</th><th>STUDENT</th><th>CLASS</th><th>%</th></tr></thead><tbody>'+rows.map((x,i)=>'<tr><td>'+(i+1)+'</td><td><b>'+esc(x.name)+'</b><small>'+esc(x.sdms||'')+'</small></td><td>'+esc(x.class_code||'—')+'</td><td><b>'+num(x.average).toFixed(1)+'%</b></td></tr>').join('')+'</tbody></table></div>'}
