function executivePerformance(host){const out=$('[data-r18674-school-perf-out]',host),btn=$('[data-r18674-school-perf]',host),mode=$('[data-r18674-school-mode]',host);if(!btn)return;btn.onclick=async()=>{btn.disabled=true;out.innerHTML='<div class="r18674-skeleton-row"></div>';try{const need=mode.value==='SUPPORT',calls=await Promise.all(['PRIMARY','SECONDARY'].map(lv=>rpc('r171_performance_analysis',{p_view:'STUDENT',p_basis:'FINAL',p_level:lv,p_class_id:null,p_subject_id:null}).catch(()=>({rows:[]}))));function normalize(d){return(d.rows||[]).map(r=>({name:r.student_name||r.full_name||r.group||r.student||'STUDENT',sdms:r.sdms_code||'',class_code:r.class_code||r.class||'',average:num(r.average!=null?r.average:r.percentage)})).filter(x=>Number.isFinite(x.average)).sort((a,b)=>need?a.average-b.average:b.average-a.average).slice(0,5)}out.innerHTML=performanceTable((need?'PRIMARY · NEED SUPPORT':'PRIMARY · TOP 5'),normalize(calls[0]))+performanceTable((need?'SECONDARY · NEED SUPPORT':'SECONDARY · TOP 5'),normalize(calls[1]))}catch(e){out.innerHTML=empty('Performance analysis is temporarily unavailable.')}finally{btn.disabled=false}}}
