function levelLabel(v){const x=up(v);if(x.includes('NURS'))return'NURSERY';if(x.includes('PRIMARY')||x.includes('LOWER')||x.includes('UPPER'))return'PRIMARY';if(x.includes('SECOND'))return'SECONDARY';return x||'OTHER'}
